package main

import (
	"context"
	"fmt"
	"io"
	"io/fs"
	"log/slog"
	"os"
	"os/exec"
	"os/signal"
	"path/filepath"
	"strings"
	"syscall"
	"text/template"
	"time"
)

const version = "0.0.0"

// Config holds all the configuration for gomplate
type Config struct {
	InputFiles      []string
	InputDir        string
	OutputFiles     []string
	OutputDir       string
	OutputMap       string
	InString        string
	Datasources     []string
	DatasourceHdrs  []string
	Contexts        []string
	Templates       []string
	Plugins         []string
	Exclude         []string
	ExcludeProc     []string
	Include         []string
	Chmod           string
	ExecPipe        bool
	LeftDelim       string
	RightDelim      string
	MissingKey      string
	Experimental    bool
	Verbose         bool
	ConfigFile      string
	PostExecArgs    []string

	// parsed datasources
	datasources map[string]*Datasource
	contexts    map[string]*Datasource
	plugins     map[string]string
	templates   []TemplateArg

	// current template file being processed
	currentTemplateFile string
}

type TemplateArg struct {
	Alias string
	Path  string
}

var gConfig *Config
var gLogger *slog.Logger
var gLogFormat string
var gVerbose bool

func init() {
	gLogFormat = os.Getenv("GOMPLATE_LOG_FORMAT")
	if gLogFormat == "" {
		if isTerm() {
			gLogFormat = "console"
		} else {
			gLogFormat = "json"
		}
	}
}

func isTerm() bool {
	fi, err := os.Stderr.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func logError(err error) {
	switch gLogFormat {
	case "console":
		fmt.Fprintf(os.Stderr, "%s ERR  error=%q\n", time.Now().Format("15:04:05"), err.Error())
	case "logfmt":
		fmt.Fprintf(os.Stderr, "time=%s level=error  error=%q\n", time.Now().UTC().Format(time.RFC3339), err.Error())
	case "simple":
		fmt.Fprintf(os.Stderr, " error=%q\n", err.Error())
	default: // json
		fmt.Fprintf(os.Stderr, "{\"time\":%q,\"level\":\"ERROR\",\"msg\":\"\",\"err\":%q}\n",
			time.Now().UTC().Format(time.RFC3339Nano), err.Error())
	}
}

func logVerbose(msg string, args ...interface{}) {
	if !gVerbose {
		return
	}
	formatted := fmt.Sprintf(msg, args...)
	switch gLogFormat {
	case "console":
		fmt.Fprintf(os.Stderr, "%s DBG  %s\n", time.Now().Format("15:04:05"), formatted)
	case "logfmt":
		fmt.Fprintf(os.Stderr, "time=%s level=debug  %s\n", time.Now().UTC().Format(time.RFC3339), formatted)
	case "simple":
		fmt.Fprintf(os.Stderr, " %s\n", formatted)
	default: // json
		fmt.Fprintf(os.Stderr, "{\"time\":%q,\"level\":\"DEBUG\",\"msg\":%q}\n",
			time.Now().UTC().Format(time.RFC3339Nano), formatted)
	}
}

func main() {
	ctx := context.Background()

	// Handle signals
	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGTERM, syscall.SIGINT)

	cfg, postExec, err := parseArgs(os.Args[1:])
	if err != nil {
		logError(fmt.Errorf("parsing args: %w", err))
		os.Exit(1)
	}

	gConfig = cfg
	gVerbose = cfg.Verbose

	if err := run(ctx, cfg, postExec); err != nil {
		logError(err)
		os.Exit(1)
	}
}

func run(ctx context.Context, cfg *Config, postExec []string) error {
	// Load config file
	if err := loadConfigFile(cfg); err != nil {
		return err
	}

	// Parse datasources
	cfg.datasources = make(map[string]*Datasource)
	for _, ds := range cfg.Datasources {
		alias, url, err := parseDatasourceArg(ds)
		if err != nil {
			return fmt.Errorf("parsing datasource %q: %w", ds, err)
		}
		cfg.datasources[alias] = &Datasource{URL: url, Headers: make(map[string][]string)}
	}
	for _, hdr := range cfg.DatasourceHdrs {
		if err := parseDatasourceHeader(hdr, cfg.datasources); err != nil {
			return fmt.Errorf("parsing datasource header %q: %w", hdr, err)
		}
	}

	// Parse contexts
	cfg.contexts = make(map[string]*Datasource)
	for _, ds := range cfg.Contexts {
		alias, url, err := parseDatasourceArg(ds)
		if err != nil {
			return fmt.Errorf("parsing context %q: %w", ds, err)
		}
		cfg.contexts[alias] = &Datasource{URL: url, Headers: make(map[string][]string)}
	}

	// Parse plugins
	cfg.plugins = make(map[string]string)
	for _, p := range cfg.Plugins {
		idx := strings.Index(p, "=")
		if idx < 0 {
			return fmt.Errorf("invalid plugin spec %q: must be in name=path form", p)
		}
		name := p[:idx]
		path := p[idx+1:]
		cfg.plugins[name] = path
	}

	// Parse templates
	cfg.templates = []TemplateArg{}
	for _, t := range cfg.Templates {
		idx := strings.Index(t, "=")
		if idx < 0 {
			// template without alias
			cfg.templates = append(cfg.templates, TemplateArg{Path: t})
		} else {
			alias := t[:idx]
			path := t[idx+1:]
			cfg.templates = append(cfg.templates, TemplateArg{Alias: alias, Path: path})
		}
	}

	// Determine input mode
	if cfg.InputDir != "" {
		return processInputDir(ctx, cfg)
	}

	// Build input/output pairs
	if cfg.InString != "" {
		// Single in-string input
		out := os.Stdout
		if len(cfg.OutputFiles) > 0 && cfg.OutputFiles[0] != "-" && !cfg.ExecPipe {
			f, err := os.Create(cfg.OutputFiles[0])
			if err != nil {
				return err
			}
			defer f.Close()
			out = f
		}

		var buf strings.Builder
		var outW io.Writer = out
		if cfg.ExecPipe && len(postExec) > 0 {
			outW = &buf
		}

		if err := processTemplate(ctx, cfg, "<arg>", cfg.InString, outW); err != nil {
			return err
		}

		if cfg.ExecPipe && len(postExec) > 0 {
			return runPostExec(postExec, buf.String())
		}

		if len(postExec) > 0 {
			return runPostExecCmd(postExec)
		}
		return nil
	}

	// File-based input
	inputs := cfg.InputFiles
	if len(inputs) == 0 {
		inputs = []string{"-"}
	}
	outputs := cfg.OutputFiles
	if len(outputs) == 0 {
		outputs = make([]string, len(inputs))
		for i := range outputs {
			outputs[i] = "-"
		}
	}

	if len(inputs) != len(outputs) {
		return fmt.Errorf("must have the same number of --file and --out arguments")
	}

	for i, inFile := range inputs {
		outFile := outputs[i]

		var inContent string
		var inName string
		var inPerm fs.FileMode = 0644

		if inFile == "-" {
			data, err := io.ReadAll(os.Stdin)
			if err != nil {
				return err
			}
			inContent = string(data)
			inName = "-"
		} else {
			data, err := os.ReadFile(inFile)
			if err != nil {
				return err
			}
			inContent = string(data)
			inName = inFile
			if fi, err := os.Stat(inFile); err == nil {
				inPerm = fi.Mode().Perm()
			}
		}

		var buf strings.Builder
		var out io.Writer = &buf

		if err := processTemplate(ctx, cfg, inName, inContent, out); err != nil {
			return err
		}

		result := buf.String()

		if outFile == "-" || cfg.ExecPipe {
			if cfg.ExecPipe && len(postExec) > 0 {
				return runPostExec(postExec, result)
			}
			fmt.Fprint(os.Stdout, result)
		} else {
			// Check if result is empty (only whitespace)
			if strings.TrimSpace(result) == "" {
				// Don't write empty output
			} else {
				mode := inPerm
				if cfg.Chmod != "" {
					m, err := parseChmod(cfg.Chmod)
					if err != nil {
						return err
					}
					mode = m
				}
				// Create parent dirs
				if dir := filepath.Dir(outFile); dir != "." {
					os.MkdirAll(dir, 0755)
				}
				if err := os.WriteFile(outFile, []byte(result), mode); err != nil {
					return err
				}
			}
		}
	}

	if len(postExec) > 0 && !cfg.ExecPipe {
		return runPostExecCmd(postExec)
	}

	return nil
}

func runPostExec(args []string, input string) error {
	if len(args) == 0 {
		return nil
	}
	cmd := exec.Command(args[0], args[1:]...)
	cmd.Stdin = strings.NewReader(input)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	return cmd.Run()
}

func runPostExecCmd(args []string) error {
	if len(args) == 0 {
		return nil
	}
	cmd := exec.Command(args[0], args[1:]...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	return cmd.Run()
}

func processInputDir(ctx context.Context, cfg *Config) error {
	// Walk input directory, process each file
	inDir := cfg.InputDir
	outDir := cfg.OutputDir
	if outDir == "" {
		outDir = "."
	}

	return filepath.WalkDir(inDir, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}

		rel, err := filepath.Rel(inDir, path)
		if err != nil {
			return err
		}

		// Check excludes/includes
		if d.IsDir() {
			return nil
		}

		if shouldExclude(rel, cfg) {
			return nil
		}

		// Determine output path
		var outPath string
		if cfg.OutputMap != "" {
			// Use template to map input to output
			mapped, err := evalOutputMap(ctx, cfg, rel)
			if err != nil {
				return err
			}
			outPath = mapped
		} else {
			outPath = filepath.Join(outDir, rel)
		}

		// Check if this file should be copied without processing
		if shouldExcludeProcessing(rel, cfg) {
			// Copy without template processing
			os.MkdirAll(filepath.Dir(outPath), 0755)
			return copyFile(path, outPath)
		}

		// Read input
		data, err := os.ReadFile(path)
		if err != nil {
			return err
		}

		fi, err := d.Info()
		if err != nil {
			return err
		}

		cfg.currentTemplateFile = path

		var buf strings.Builder
		if err := processTemplate(ctx, cfg, path, string(data), &buf); err != nil {
			return err
		}

		result := buf.String()
		if strings.TrimSpace(result) == "" {
			return nil
		}

		mode := fi.Mode().Perm()
		if cfg.Chmod != "" {
			m, err := parseChmod(cfg.Chmod)
			if err != nil {
				return err
			}
			mode = m
		}

		os.MkdirAll(filepath.Dir(outPath), 0755)
		return os.WriteFile(outPath, []byte(result), mode)
	})
}

func copyFile(src, dst string) error {
	data, err := os.ReadFile(src)
	if err != nil {
		return err
	}
	fi, err := os.Stat(src)
	if err != nil {
		return err
	}
	return os.WriteFile(dst, data, fi.Mode().Perm())
}

func evalOutputMap(ctx context.Context, cfg *Config, rel string) (string, error) {
	// Create a special context for output map evaluation
	rootCtx := buildContext(ctx, cfg)
	mapCtx := map[string]interface{}{
		"in":  rel,
		"ctx": rootCtx,
	}
	// Copy root context keys if they don't conflict
	if rootMap, ok := rootCtx.(map[string]interface{}); ok {
		for k, v := range rootMap {
			if k != "in" && k != "ctx" {
				mapCtx[k] = v
			}
		}
	}

	var buf strings.Builder
	t, err := createTemplate(cfg, "<output-map>")
	if err != nil {
		return "", err
	}
	t, err = t.Parse(cfg.OutputMap)
	if err != nil {
		return "", err
	}
	if err := t.Execute(&buf, mapCtx); err != nil {
		return "", err
	}
	return strings.TrimSpace(buf.String()), nil
}

func processTemplate(ctx context.Context, cfg *Config, name string, content string, out io.Writer) error {
	cfg.currentTemplateFile = name

	t, err := createTemplate(cfg, name)
	if err != nil {
		return fmt.Errorf("parse template %s: %w", name, err)
	}

	// Load external templates
	for _, ta := range cfg.templates {
		if err := loadExternalTemplates(t, ta); err != nil {
			return fmt.Errorf("loading template %q: %w", ta.Path, err)
		}
	}

	t, err = t.Parse(content)
	if err != nil {
		return fmt.Errorf("renderTemplate: parse template %s: %w", name, err)
	}

	data := buildContext(ctx, cfg)

	if err := t.Execute(out, data); err != nil {
		return fmt.Errorf("renderTemplate: failed to render template %s: %w", name, err)
	}

	return nil
}

func loadExternalTemplates(t *template.Template, ta TemplateArg) error {
	path := ta.Path
	alias := ta.Alias

	// Check if path ends with "/" (directory)
	if strings.HasSuffix(path, "/") || strings.HasSuffix(path, string(os.PathSeparator)) {
		// Load all files from directory
		return filepath.WalkDir(path, func(fpath string, d fs.DirEntry, err error) error {
			if err != nil {
				return err
			}
			if d.IsDir() {
				return nil
			}
			data, err := os.ReadFile(fpath)
			if err != nil {
				return err
			}
			rel, err := filepath.Rel(filepath.Dir(strings.TrimSuffix(path, "/")), fpath)
			if err != nil {
				return err
			}
			tmplName := rel
			if alias != "" {
				tmplName = alias + "/" + filepath.Base(fpath)
			}
			_, err = t.New(tmplName).Parse(string(data))
			return err
		})
	}

	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}

	name := alias
	if name == "" {
		name = filepath.Base(path)
	}
	_, err = t.New(name).Parse(string(data))
	return err
}

func shouldExclude(rel string, cfg *Config) bool {
	// Include patterns take priority - if include list is set, only include matching
	if len(cfg.Include) > 0 {
		matches := false
		for _, pat := range cfg.Include {
			ok, _ := filepath.Match(pat, filepath.Base(rel))
			if !ok {
				ok, _ = filepath.Match(pat, rel)
			}
			if ok {
				matches = true
				break
			}
		}
		if !matches {
			return true
		}
	}

	// Check exclude patterns
	for _, pat := range cfg.Exclude {
		negated := strings.HasPrefix(pat, "!")
		actualPat := pat
		if negated {
			actualPat = pat[1:]
		}
		ok, _ := filepath.Match(actualPat, filepath.Base(rel))
		if !ok {
			ok, _ = filepath.Match(actualPat, rel)
		}
		if ok {
			if negated {
				return false // explicitly included
			}
			return true
		}
	}
	return false
}

func shouldExcludeProcessing(rel string, cfg *Config) bool {
	for _, pat := range cfg.ExcludeProc {
		ok, _ := filepath.Match(pat, filepath.Base(rel))
		if !ok {
			ok, _ = filepath.Match(pat, rel)
		}
		if ok {
			return true
		}
	}
	return false
}

func parseChmod(s string) (fs.FileMode, error) {
	var mode uint32
	for _, c := range s {
		if c < '0' || c > '7' {
			return 0, fmt.Errorf("invalid chmod value: %s", s)
		}
		mode = mode*8 + uint32(c-'0')
	}
	return fs.FileMode(mode), nil
}
