			inContent = string(data)
			inName = "-"
		} else {
			data, err := os.ReadFile(inFile)
			if err != nil {
				return err
			}
			inContent = string(data)
			inName = inFile
			if fi, err := os.Stat(inFile); err == nil {
				inPerm = fi.Mode().Perm()
			}
		}

		var buf strings.Builder
		var out io.Writer = &buf

		if err := processTemplate(ctx, cfg, inName, inContent, out); err != nil {
			return err
		}

		result := buf.String()

		if outFile == "-" || cfg.ExecPipe {
			if cfg.ExecPipe && len(postExec) > 0 {
				return runPostExec(postExec, result)
			}
			fmt.Fprint(os.Stdout, result)
		} else {
			// Check if result is empty (only whitespace)
			if strings.TrimSpace(result) == "" {
				// Don't write empty output
			} else {
				mode := inPerm
				if cfg.Chmod != "" {
					m, err := parseChmod(cfg.Chmod)
					if err != nil {
						return err
					}
					mode = m
				}
				// Create parent dirs
				if dir := filepath.Dir(outFile); dir != "." {
					os.MkdirAll(dir, 0755)
				}
				if err := os.WriteFile(outFile, []byte(result), mode); err != nil {
					return err
				}
			}
		}
	}

	if len(postExec) > 0 && !cfg.ExecPipe {
		return runPostExecCmd(postExec)
	}

	return nil
}

func runPostExec(args []string, input string) error {
	if len(args) == 0 {
