	_, err = t.New(name).Parse(string(data))
	return err
}

func shouldExclude(rel string, cfg *Config) bool {
	// Include patterns take priority - if include list is set, only include matching
	if len(cfg.Include) > 0 {
		matches := false
		for _, pat := range cfg.Include {
			ok, _ := filepath.Match(pat, filepath.Base(rel))
			if !ok {
				ok, _ = filepath.Match(pat, rel)
			}
			if ok {
				matches = true
				break
			}
		}
		if !matches {
			return true
		}
	}

	// Check exclude patterns
	for _, pat := range cfg.Exclude {
		negated := strings.HasPrefix(pat, "!")
		actualPat := pat
		if negated {
			actualPat = pat[1:]
		}
		ok, _ := filepath.Match(actualPat, filepath.Base(rel))
		if !ok {
			ok, _ = filepath.Match(actualPat, rel)
		}
		if ok {
			if negated {
				return false // explicitly included
			}
			return true
		}
	}
	return false
}

func shouldExcludeProcessing(rel string, cfg *Config) bool {
	for _, pat := range cfg.ExcludeProc {
		ok, _ := filepath.Match(pat, filepath.Base(rel))
		if !ok {
			ok, _ = filepath.Match(pat, rel)
		}
		if ok {
			return true
		}
	}
	return false
}

func parseChmod(s string) (fs.FileMode, error) {
	var mode uint32
	for _, c := range s {
		if c < '0' || c > '7' {
			return 0, fmt.Errorf("invalid chmod value: %s", s)
		}
		mode = mode*8 + uint32(c-'0')
	}
	return fs.FileMode(mode), nil
}
