const version = "0.0.0"

// Config holds all the configuration for gomplate
type Config struct {
	InputFiles      []string
	InputDir        string
	OutputFiles     []string
	OutputDir       string
	OutputMap       string
	InString        string
	Datasources     []string
	DatasourceHdrs  []string
	Contexts        []string
	Templates       []string
	Plugins         []string
	Exclude         []string
	ExcludeProc     []string
	Include         []string
	Chmod           string
	ExecPipe        bool
	LeftDelim       string
	RightDelim      string
	MissingKey      string
