// loadConfigFile loads configuration from the config file
func loadConfigFile(cfg *Config) error {
	configFile := cfg.ConfigFile

	// If config file is empty string, skip
	if configFile == "" {
		return nil
	}

	// Try to read the config file
	data, err := os.ReadFile(configFile)
	if err != nil {
		if os.IsNotExist(err) {
			// Config file not found - that's ok if it's the default
			if configFile == ".gomplate.yaml" {
				return nil
			}
			return fmt.Errorf("config file %q not found", configFile)
		}
		return err
	}

	// Parse YAML config
	return parseYAMLConfig(cfg, string(data))
}

func parseYAMLConfig(cfg *Config, content string) error {
	// Parse the YAML config file manually
	// We use our simple YAML parser
	m, err := parseSimpleYAML(content)
	if err != nil {
		return fmt.Errorf("parsing config file: %w", err)
	}

	if v, ok := m["in"]; ok {
		if cfg.InString == "" { // command line takes precedence
			cfg.InString = fmt.Sprintf("%v", v)
		}
	}

	if v, ok := m["inputDir"]; ok {
		if cfg.InputDir == "" {
			cfg.InputDir = fmt.Sprintf("%v", v)
		}
	}

	if v, ok := m["outputDir"]; ok {
		if cfg.OutputDir == "" {
			cfg.OutputDir = fmt.Sprintf("%v", v)
		}
	}

	if v, ok := m["outputMap"]; ok {
		if cfg.OutputMap == "" {
			cfg.OutputMap = fmt.Sprintf("%v", v)
		}
	}

	if v, ok := m["chmod"]; ok {
		if cfg.Chmod == "" {
			cfg.Chmod = fmt.Sprintf("%v", v)
		}
	}

	if v, ok := m["leftDelim"]; ok {
		if cfg.LeftDelim == "{{" {
			cfg.LeftDelim = fmt.Sprintf("%v", v)
		}
	}

	if v, ok := m["rightDelim"]; ok {
		if cfg.RightDelim == "}}" {
			cfg.RightDelim = fmt.Sprintf("%v", v)
		}
	}

	if v, ok := m["missingKey"]; ok {
		if cfg.MissingKey == "error" {
			cfg.MissingKey = fmt.Sprintf("%v", v)
		}
	}

	if v, ok := m["experimental"]; ok {
		if !cfg.Experimental {
			cfg.Experimental = fmt.Sprintf("%v", v) == "true"
		}
	}

	if v, ok := m["execPipe"]; ok {
		if !cfg.ExecPipe {
			cfg.ExecPipe = fmt.Sprintf("%v", v) == "true"
		}
	}

	// Parse inputFiles
	if v, ok := m["inputFiles"]; ok {
		if len(cfg.InputFiles) == 0 {
			if files, ok := v.([]interface{}); ok {
				for _, f := range files {
					cfg.InputFiles = append(cfg.InputFiles, fmt.Sprintf("%v", f))
				}
			}
		}
	}

	// Parse outputFiles
	if v, ok := m["outputFiles"]; ok {
		if len(cfg.OutputFiles) == 0 {
			if files, ok := v.([]interface{}); ok {
				for _, f := range files {
					cfg.OutputFiles = append(cfg.OutputFiles, fmt.Sprintf("%v", f))
				}
			}
		}
	}

	// Parse datasources
	if v, ok := m["datasources"]; ok {
		if dsMap, ok := v.(map[string]interface{}); ok {
			for alias, dsv := range dsMap {
				if dsMap2, ok := dsv.(map[string]interface{}); ok {
					if url, ok := dsMap2["url"]; ok {
						cfg.Datasources = append(cfg.Datasources, fmt.Sprintf("%s=%v", alias, url))
					}
					if hdrs, ok := dsMap2["header"]; ok {
						if hdrMap, ok := hdrs.(map[string]interface{}); ok {
							for hname, hvals := range hdrMap {
								if hlist, ok := hvals.([]interface{}); ok {
									for _, hval := range hlist {
										cfg.DatasourceHdrs = append(cfg.DatasourceHdrs, fmt.Sprintf("%s=%s: %v", alias, hname, hval))
									}
								}
							}
						}
					}
				}
			}
		}
	}

	// Parse context
	if v, ok := m["context"]; ok {
		if ctxMap, ok := v.(map[string]interface{}); ok {
			for alias, dsv := range ctxMap {
				if dsMap2, ok := dsv.(map[string]interface{}); ok {
					if url, ok := dsMap2["url"]; ok {
						cfg.Contexts = append(cfg.Contexts, fmt.Sprintf("%s=%v", alias, url))
					}
				}
			}
		}
	}

	// Parse plugins
	if v, ok := m["plugins"]; ok {
		if pluginMap, ok := v.(map[string]interface{}); ok {
			for name, path := range pluginMap {
				if pathStr, ok := path.(string); ok {
					cfg.Plugins = append(cfg.Plugins, fmt.Sprintf("%s=%s", name, pathStr))
				} else if pathMap, ok := path.(map[string]interface{}); ok {
