					}
				}
			}
		}
	}

	// Parse templates
	if v, ok := m["templates"]; ok {
		if tmplMap, ok := v.(map[string]interface{}); ok {
			for alias, path := range tmplMap {
				cfg.Templates = append(cfg.Templates, fmt.Sprintf("%s=%v", alias, path))
			}
