// parseDatasourceArg parses "alias=URL" or just "URL" 
func parseDatasourceArg(s string) (string, string, error) {
	// Find the alias=URL split
	// The alias can't contain ':' or '/' but the URL can
	// So we need to find the first '=' that's before any ':' or '/'

	eqIdx := strings.IndexByte(s, '=')
	if eqIdx < 0 {
		// No alias, just a URL - alias is derived from URL
		alias := deriveAlias(s)
		return alias, s, nil
	}

	// Check if the '=' is actually part of a URL scheme (e.g., no: before =)
	colonIdx := strings.IndexByte(s, ':')
	if colonIdx >= 0 && colonIdx < eqIdx {
		// The '=' is after a ':', so it's part of a URL
		alias := deriveAlias(s)
		return alias, s, nil
	}

	alias := s[:eqIdx]
	url := s[eqIdx+1:]

	return alias, url, nil
}

func deriveAlias(url string) string {
	// Strip scheme
	if idx := strings.Index(url, "://"); idx >= 0 {
		url = url[idx+3:]
	}
	// Take first path component
	url = strings.TrimPrefix(url, "/")
	if idx := strings.IndexAny(url, "/?#"); idx >= 0 {
		url = url[:idx]
	}
	// Take base name
	if idx := strings.LastIndexByte(url, '/'); idx >= 0 {
		url = url[idx+1:]
	}
	// Strip extension
	if idx := strings.LastIndexByte(url, '.'); idx >= 0 {
		url = url[:idx]
	}
	return url
}

func parseDatasourceHeader(s string, sources map[string]*Datasource) error {
	// Format: "alias=Name: value"
	eqIdx := strings.IndexByte(s, '=')
	if eqIdx < 0 {
		return fmt.Errorf("invalid datasource header %q: must be in alias=Name: value form", s)
	}
	alias := s[:eqIdx]
	rest := s[eqIdx+1:]

	colonIdx := strings.IndexByte(rest, ':')
	if colonIdx < 0 {
		return fmt.Errorf("invalid datasource header %q: must be in alias=Name: value form", s)
	}
	name := rest[:colonIdx]
	value := strings.TrimSpace(rest[colonIdx+1:])

	ds, ok := sources[alias]
	if !ok {
		// Create the datasource if it doesn't exist
		sources[alias] = &Datasource{Headers: make(map[string][]string)}
		ds = sources[alias]
	}
	if ds.Headers == nil {
		ds.Headers = make(map[string][]string)
	}
	ds.Headers[name] = append(ds.Headers[name], value)

	return nil
}
