	if idx := strings.Index(rawURL, "://"); idx >= 0 {
		scheme = rawURL[:idx]
		rest := rawURL[idx+3:]
		// Split query
		if qIdx := strings.Index(rest, "?"); qIdx >= 0 {
			queryStr := rest[qIdx+1:]
			rest = rest[:qIdx]
			// Parse query string
			for _, part := range strings.Split(queryStr, "&") {
				if eqIdx := strings.Index(part, "="); eqIdx >= 0 {
					query[part[:eqIdx]] = part[eqIdx+1:]
				}
			}
