		// Strip authority for env: scheme (env:///FOO -> /FOO)
		if strings.HasPrefix(rest, "/") {
			path = rest
		} else {
			path = rest
		}
		return
	}

	// Opaque URI (like aws+smp:mykey)
	if idx := strings.IndexByte(rawURL, ':'); idx >= 0 {
		scheme = rawURL[:idx]
		path = rawURL[idx+1:]
		// Not a regular file path
		if strings.HasPrefix(path, "/") {
			// It's actually a file path with drive letter? Unlikely on Linux
		}
		return
	}

	// Plain file path
	scheme = "file"
	path = rawURL
	return
}

