	// Check query override
	typeParam := os.Getenv("GOMPLATE_TYPE_PARAM")
	if typeParam == "" {
		typeParam = "type"
	}
	if t, ok := query[typeParam]; ok {
		return t
	}

	// Infer from extension
	if idx := strings.LastIndexByte(path, '.'); idx >= 0 {
		ext := strings.ToLower(path[idx:])
		switch ext {
		case ".json":
			return "application/json"
		case ".yaml", ".yml":
			return "application/yaml"
		case ".toml":
			return "application/toml"
		case ".csv":
			return "text/csv"
		case ".env":
			return "application/x-env"
		case ".txt":
			return "text/plain"
		}
	}

	// For env datasources, default to text
	if scheme == "env" {
		return "text/plain"
	}

	return "application/json" // default
}

func parseDatasourceData(data []byte, mimeType string) (interface{}, error) {
	// Strip mime type params
	baseMime := mimeType
	if idx := strings.IndexByte(mimeType, ';'); idx >= 0 {
		baseMime = strings.TrimSpace(mimeType[:idx])
	}

	switch baseMime {
	case "application/json":
		return parseJSON(string(data))
	case "application/array+json":
		return parseJSONArray(string(data))
	case "application/yaml", "application/x-yaml", "text/yaml":
		return parseYAML(string(data))
	case "application/toml":
		return parseTOML(string(data))
	case "text/csv":
