	case "application/x-env":
		return parseEnvFile(string(data))
	case "text/plain":
		return string(data), nil
	default:
		// Try JSON first
		v, err := parseJSON(string(data))
		if err == nil {
			return v, nil
		}
		return string(data), nil
	}
