package main

import (
	"context"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"text/template"
	"time"
)

// createTemplate creates a new template with all the gomplate functions
func createTemplate(cfg *Config, name string) (*template.Template, error) {
	t := template.New(name)

	// Set delimiters
	t = t.Delims(cfg.LeftDelim, cfg.RightDelim)

	// Set missing key behavior
	switch cfg.MissingKey {
	case "zero":
		t = t.Option("missingkey=zero")
	case "default", "invalid":
		t = t.Option("missingkey=default")
	default: // "error"
		t = t.Option("missingkey=error")
	}

	// Register all functions
	funcs := buildFuncMap(cfg)
	t = t.Funcs(funcs)

	return t, nil
}

// buildFuncMap creates all template functions
func buildFuncMap(cfg *Config) template.FuncMap {
	fm := template.FuncMap{}

	// Built-in go template functions that we override or augment
	// (go template already has: and, or, not, len, index, slice, print, printf, println, html, urlquery, js, call, eq, ne, lt, le, gt, ge)

	// Env functions
	fm["getenv"] = func(key string, def ...string) string {
		return getenvWithFileFallback(key, def...)
	}

	// Math functions
	addMathFuncs(fm)

	// String functions
	addStringFuncs(fm)

	// Conversion functions
	addConvFuncs(fm)

	// Collection functions
	addCollFuncs(fm)

	// Data functions
	addDataFuncs(fm)

	// Crypto functions
	addCryptoFuncs(fm)

	// Base64 functions
	addBase64Funcs(fm)

	// Time functions
	addTimeFuncs(fm)

	// UUID functions
	addUUIDFuncs(fm)

	// Random functions
	addRandomFuncs(fm)

	// Net functions
	addNetFuncs(fm)

	// Path functions
	addPathFuncs(fm)

	// Filepath functions  
	addFilepathFuncs(fm)

	// File functions
	addFileFuncs(fm)

	// Regexp functions
	addRegexpFuncs(fm)

	// Test functions
	addTestFuncs(fm)

	// Template/tmpl functions
	addTmplFuncs(fm, cfg)

	// Sockaddr functions
	addSockaddrFuncs(fm)

	// Semver functions
	addSemverFuncs(fm)

	// AWS functions (stubs)
	addAWSFuncs(fm)

	// GCP functions (stubs)
	addGCPFuncs(fm)

	// Datasource functions
	addDatasourceFuncs(fm, cfg)

	// Plugin functions
	for name, pluginPath := range cfg.plugins {
		name := name
		pluginPath := pluginPath
		fm[name] = makePluginFunc(name, pluginPath, cfg)
	}

	// Namespace objects
	fm["math"] = &MathNS{}
	fm["strings"] = &StringsNS{}
	fm["conv"] = &ConvNS{}
	fm["coll"] = &CollNS{}
	fm["data"] = &DataNS{}
	fm["crypto"] = &CryptoNS{}
	fm["base64"] = &Base64NS{}
	fm["time"] = &TimeNS{}
	fm["uuid"] = &UUIDNS{}
	fm["random"] = &RandomNS{}
	fm["net"] = &NetNS{}
	fm["path"] = &PathNS{}
	fm["filepath"] = &FilepathNS{}
	fm["file"] = &FileNS{}
	fm["regexp"] = &RegexpNS{}
	fm["test"] = &TestNS{}
	fm["tmpl"] = newTmplNS(cfg)
	fm["sockaddr"] = &SockaddrNS{}
	fm["semver"] = &SemverNS{}
	fm["aws"] = &AWSNS{}
	fm["gcp"] = &GCPNS{}
	fm["env"] = &EnvNS{}

	return fm
}

func makePluginFunc(name, pluginPath string, cfg *Config) interface{} {
	return func(args ...interface{}) (string, error) {
		timeout := 5 * time.Second
		if v := os.Getenv("GOMPLATE_PLUGIN_TIMEOUT"); v != "" {
			if d, err := time.ParseDuration(v); err == nil {
				timeout = d
			}
		}

		strArgs := make([]string, len(args))
		for i, a := range args {
			strArgs[i] = fmt.Sprintf("%v", a)
		}

		ctx, cancel := context.WithTimeout(context.Background(), timeout)
		defer cancel()

		cmd := exec.CommandContext(ctx, pluginPath, strArgs...)
		cmd.Stderr = os.Stderr
		out, err := cmd.Output()
		if err != nil {
			return "", fmt.Errorf("plugin %q failed: %w", name, err)
		}
		return string(out), nil
	}
}

// TmplNS namespace
type TmplNS struct {
	cfg *Config
}

func newTmplNS(cfg *Config) *TmplNS {
	return &TmplNS{cfg: cfg}
}

func (ns *TmplNS) Exec(name string, ctx ...interface{}) (string, error) {
	t, err := createTemplate(ns.cfg, name)
	if err != nil {
		return "", err
	}
	// Load external templates
	for _, ta := range ns.cfg.templates {
		if err := loadExternalTemplates(t, ta); err != nil {
			return "", err
		}
	}

	// We need to find the template
	tmpl := t.Lookup(name)
	if tmpl == nil {
		return "", fmt.Errorf("template %q not found", name)
	}

	var data interface{}
	if len(ctx) > 0 {
		data = ctx[0]
	}

	var buf strings.Builder
	if err := tmpl.Execute(&buf, data); err != nil {
		return "", err
	}
	return buf.String(), nil
}

func (ns *TmplNS) Inline(args ...interface{}) (string, error) {
	// tmpl.Inline [name] in [context]
	if len(args) == 0 {
		return "", fmt.Errorf("tmpl.Inline requires at least one argument")
	}

	var name, in string
	var ctx interface{}

	switch len(args) {
	case 1:
		in = fmt.Sprintf("%v", args[0])
	case 2:
		// Could be (name, in) or (in, context)
		// If second arg is a string, assume (name, in)
		// If second arg is non-string, assume (in, context)
		s0 := fmt.Sprintf("%v", args[0])
		switch args[1].(type) {
		case string:
			name = s0
			in = fmt.Sprintf("%v", args[1])
		default:
			in = s0
			ctx = args[1]
		}
	case 3:
		name = fmt.Sprintf("%v", args[0])
		in = fmt.Sprintf("%v", args[1])
		ctx = args[2]
	}

	t, err := createTemplate(ns.cfg, "<inline>")
	if err != nil {
		return "", err
	}

	if name != "" {
		t, err = t.New(name).Parse(in)
	} else {
		t, err = t.Parse(in)
	}
	if err != nil {
		return "", err
	}

	var buf strings.Builder
	if err := t.Execute(&buf, ctx); err != nil {
		return "", err
	}
	return buf.String(), nil
}

func (ns *TmplNS) Path() string {
	return ns.cfg.currentTemplateFile
}

func addTmplFuncs(fm template.FuncMap, cfg *Config) {
	tmplNS := newTmplNS(cfg)
	fm["tpl"] = func(args ...interface{}) (string, error) {
		return tmplNS.Inline(args...)
	}
}
