)

// EnvNS is the env namespace
type EnvNS struct{}

func (ns *EnvNS) Getenv(key string, def ...string) string {
	return getenvWithFileFallback(key, def...)
}

func (ns *EnvNS) Env() map[string]string {
	return envMap()
}

func (ns *EnvNS) HasEnv(key string) bool {
	_, ok := os.LookupEnv(key)
	return ok
}

func (ns *EnvNS) ExpandEnv(s string) string {
	return os.Expand(s, func(key string) string {
		return getenvWithFileFallback(key)
	})
}

func getenvWithFileFallback(key string, defaultVal ...string) string {
	val, ok := os.LookupEnv(key)
	if ok {
		return val
	}

	// Try _FILE variant
	fileKey := key + "_FILE"
	filePath := os.Getenv(fileKey)
	if filePath != "" {
		data, err := os.ReadFile(filePath)
		if err == nil {
			return strings.TrimRight(string(data), "\n")
		}
	}

	if len(defaultVal) > 0 {
		return defaultVal[0]
	}
	return ""
}

func hasEnv(key string) bool {
	_, ok := os.LookupEnv(key)
	return ok
}

func envMap() map[string]string {
	m := make(map[string]string)
	for _, env := range os.Environ() {
		parts := strings.SplitN(env, "=", 2)
		if len(parts) == 2 {
			m[parts[0]] = parts[1]
		} else {
			m[parts[0]] = ""
		}
	}
	return m
}
