package main

import (
	"fmt"
	"math"
	"strconv"
)

// MathNS is the math namespace
type MathNS struct{}

func (ns *MathNS) Abs(n interface{}) (interface{}, error) {
	switch v := n.(type) {
	case int64:
		if v < 0 {
			return -v, nil
		}
		return v, nil
	case int:
		if v < 0 {
			return int64(-v), nil
		}
		return int64(v), nil
	default:
		f, err := toFloat64(n)
		if err != nil {
			return nil, err
		}
		return math.Abs(f), nil
	}
}

func (ns *MathNS) Add(nums ...interface{}) (interface{}, error) {
	return mathAdd(nums...)
}

func (ns *MathNS) Ceil(n interface{}) (float64, error) {
	f, err := toFloat64(n)
	if err != nil {
		return 0, err
	}
	return math.Ceil(f), nil
}

func (ns *MathNS) Div(a, b interface{}) (interface{}, error) {
	return mathDiv(a, b)
}

func (ns *MathNS) Floor(n interface{}) (float64, error) {
	f, err := toFloat64(n)
	if err != nil {
		return 0, err
	}
	return math.Floor(f), nil
}

func (ns *MathNS) IsFloat(n interface{}) bool {
	switch n.(type) {
	case float32, float64:
		return true
	default:
		return false
	}
}

func (ns *MathNS) IsInt(n interface{}) bool {
	switch n.(type) {
	case int, int8, int16, int32, int64,
		uint, uint8, uint16, uint32, uint64:
		return true
	default:
		return false
	}
}

func (ns *MathNS) IsNum(n interface{}) bool {
	switch n.(type) {
	case int, int8, int16, int32, int64,
		uint, uint8, uint16, uint32, uint64,
		float32, float64:
		return true
	case string:
		s := n.(string)
		_, err := strconv.ParseFloat(s, 64)
		return err == nil
	default:
		return false
	}
}

func (ns *MathNS) Max(nums ...interface{}) (interface{}, error) {
	return mathMax(nums...)
}

func (ns *MathNS) Min(nums ...interface{}) (interface{}, error) {
	return mathMin(nums...)
}

func (ns *MathNS) Mul(nums ...interface{}) (interface{}, error) {
	return mathMul(nums...)
}

func (ns *MathNS) Pow(a, b interface{}) (interface{}, error) {
	af, err := toFloat64(a)
	if err != nil {
		return nil, err
	}
	bf, err := toFloat64(b)
	if err != nil {
		return nil, err
	}
	result := math.Pow(af, bf)
	// Return int if both inputs are integers and result is whole
	if isIntType(a) && isIntType(b) && result == math.Trunc(result) {
		return int64(result), nil
	}
	return result, nil
}

func (ns *MathNS) Rem(a, b interface{}) (interface{}, error) {
	return mathRem(a, b)
}

func (ns *MathNS) Round(n interface{}) (interface{}, error) {
	f, err := toFloat64(n)
	if err != nil {
		return nil, err
	}
	return math.Round(f), nil
}

func (ns *MathNS) Seq(nums ...interface{}) ([]int64, error) {
	switch len(nums) {
	case 1:
		end, err := toInt64(nums[0])
		if err != nil {
			return nil, err
		}
		return mathSeq(0, end, 1), nil
	case 2:
		start, err := toInt64(nums[0])
		if err != nil {
			return nil, err
		}
		end, err := toInt64(nums[1])
		if err != nil {
			return nil, err
		}
		step := int64(1)
		if end < start {
			step = -1
		}
		return mathSeq(start, end, step), nil
	case 3:
		start, err := toInt64(nums[0])
		if err != nil {
			return nil, err
		}
		end, err := toInt64(nums[1])
		if err != nil {
			return nil, err
		}
		step, err := toInt64(nums[2])
		if err != nil {
			return nil, err
		}
		return mathSeq(start, end, step), nil
	default:
		return nil, fmt.Errorf("math.Seq requires 1, 2 or 3 arguments")
	}
}

func (ns *MathNS) Sub(a, b interface{}) (interface{}, error) {
	return mathSub(a, b)
}

// Aliases
func addMathFuncs(fm interface{ Set(string, interface{}) }) {
}

func mathAdd(nums ...interface{}) (interface{}, error) {
	if len(nums) == 0 {
		return int64(0), nil
	}

	isFloat := false
	for _, n := range nums {
		if isFloatType(n) {
			isFloat = true
			break
		}
		// Check string with decimal
		if s, ok := n.(string); ok {
			if isFloatString(s) {
				isFloat = true
				break
			}
		}
	}

	if isFloat {
		sum := 0.0
		for _, n := range nums {
			f, err := toFloat64(n)
			if err != nil {
				return nil, err
			}
			sum += f
		}
		return sum, nil
	}

	sum := int64(0)
	for _, n := range nums {
		i, err := toInt64(n)
		if err != nil {
			return nil, err
		}
		sum += i
	}
	return sum, nil
}

func mathSub(a, b interface{}) (interface{}, error) {
	if isFloatType(a) || isFloatType(b) || isFloatString(fmt.Sprintf("%v", a)) || isFloatString(fmt.Sprintf("%v", b)) {
		af, err := toFloat64(a)
		if err != nil {
			return nil, err
		}
		bf, err := toFloat64(b)
		if err != nil {
			return nil, err
		}
		return af - bf, nil
	}
	ai, err := toInt64(a)
	if err != nil {
		return nil, err
	}
	bi, err := toInt64(b)
	if err != nil {
		return nil, err
	}
	return ai - bi, nil
}

func mathMul(nums ...interface{}) (interface{}, error) {
	if len(nums) == 0 {
		return int64(1), nil
	}

	isFloat := false
	for _, n := range nums {
		if isFloatType(n) {
			isFloat = true
			break
		}
		if s, ok := n.(string); ok {
			if isFloatString(s) {
				isFloat = true
				break
			}
		}
	}

	if isFloat {
		product := 1.0
		for _, n := range nums {
			f, err := toFloat64(n)
			if err != nil {
				return nil, err
			}
			product *= f
		}
		return product, nil
	}

	product := int64(1)
	for _, n := range nums {
		i, err := toInt64(n)
		if err != nil {
			return nil, err
		}
		product *= i
	}
	return product, nil
}

func mathDiv(a, b interface{}) (interface{}, error) {
	// Division always returns float
	af, err := toFloat64(a)
	if err != nil {
		return nil, err
	}
	bf, err := toFloat64(b)
	if err != nil {
		return nil, err
	}
	if bf == 0 {
		return nil, fmt.Errorf("division by zero")
	}
	return af / bf, nil
}

func mathRem(a, b interface{}) (interface{}, error) {
	ai, err := toInt64(a)
	if err != nil {
		return nil, err
	}
	bi, err := toInt64(b)
	if err != nil {
		return nil, err
	}
	if bi == 0 {
		return nil, fmt.Errorf("division by zero")
	}
	return ai % bi, nil
}

func mathMax(nums ...interface{}) (interface{}, error) {
	if len(nums) == 0 {
		return nil, fmt.Errorf("math.Max requires at least one argument")
	}

	isFloat := false
	for _, n := range nums {
		if isFloatType(n) {
			isFloat = true
			break
		}
	}

	if isFloat {
		max := math.Inf(-1)
		for _, n := range nums {
			f, err := toFloat64(n)
			if err != nil {
				return nil, err
			}
			if f > max {
				max = f
			}
		}
		return max, nil
	}

	var max int64 = math.MinInt64
	for _, n := range nums {
		i, err := toInt64(n)
		if err != nil {
			return nil, err
		}
		if i > max {
			max = i
		}
	}
	return max, nil
}

func mathMin(nums ...interface{}) (interface{}, error) {
	if len(nums) == 0 {
		return nil, fmt.Errorf("math.Min requires at least one argument")
	}

	isFloat := false
	for _, n := range nums {
		if isFloatType(n) {
			isFloat = true
			break
		}
	}

	if isFloat {
		min := math.Inf(1)
		for _, n := range nums {
			f, err := toFloat64(n)
			if err != nil {
				return nil, err
			}
			if f < min {
				min = f
			}
		}
		return min, nil
	}

	var min int64 = math.MaxInt64
	for _, n := range nums {
		i, err := toInt64(n)
		if err != nil {
			return nil, err
		}
		if i < min {
			min = i
		}
	}
	return min, nil
}

func mathSeq(start, end, step int64) []int64 {
	if step == 0 {
		return []int64{}
	}
	if end < start && step > 0 {
		step = -step
	}
	if end > start && step < 0 {
		step = -step
	}

	// Adjust end to align
	if step != 0 {
		end -= (end - start) % step
	}

	seq := []int64{start}
	last := start
	for last != end {
		last = seq[len(seq)-1] + step
		seq = append(seq, last)
	}
	return seq
}

func isFloatType(v interface{}) bool {
	switch v.(type) {
	case float32, float64:
		return true
	}
	return false
}

func isIntType(v interface{}) bool {
	switch v.(type) {
	case int, int8, int16, int32, int64,
		uint, uint8, uint16, uint32, uint64:
		return true
	}
	return false
}

func isFloatString(s string) bool {
	if _, err := strconv.ParseInt(s, 0, 64); err == nil {
		return false
	}
	_, err := strconv.ParseFloat(s, 64)
	return err == nil
}

