func toInt64(in interface{}) (int64, error) {
	switch v := in.(type) {
	case int:
		return int64(v), nil
	case int8:
		return int64(v), nil
	case int16:
		return int64(v), nil
	case int32:
		return int64(v), nil
	case int64:
		return v, nil
	case uint:
		return int64(v), nil
	case uint8:
		return int64(v), nil
	case uint16:
		return int64(v), nil
	case uint32:
		return int64(v), nil
	case uint64:
		return int64(v), nil
	case float32:
		return int64(v), nil
	case float64:
		return int64(v), nil
	case bool:
		if v {
			return 1, nil
		}
		return 0, nil
	case string:
		// Try hex, octal, decimal
		n, err := strconv.ParseInt(v, 0, 64)
		if err == nil {
			return n, nil
		}
		// Try as float
		f, err2 := strconv.ParseFloat(v, 64)
		if err2 == nil {
			return int64(f), nil
		}
		return 0, fmt.Errorf("could not convert %q to int64: %w", v, err)
	case nil:
		return 0, nil
	default:
		return 0, fmt.Errorf("could not convert %T to int64", in)
	}
}

