func (ns *CollNS) GoSlice(args ...interface{}) (interface{}, error) {
	// This is the built-in slice operation
	if len(args) == 0 {
		return nil, fmt.Errorf("slice requires at least one argument")
	}

	val := reflect.ValueOf(args[0])
	indices := args[1:]

	switch val.Kind() {
