}

func (ns *CollNS) Has(in interface{}, item interface{}) bool {
	switch v := in.(type) {
	case map[string]interface{}:
		key := toString(item)
		_, ok := v[key]
		return ok
	case []interface{}:
		for _, e := range v {
			if reflect.DeepEqual(e, item) {
				return true
			}
			if toString(e) == toString(item) {
				return true
			}
		}
		return false
	case []string:
		for _, e := range v {
			if e == toString(item) {
				return true
			}
		}
		return false
	default:
		// Use reflection
		rv := reflect.ValueOf(in)
		if rv.Kind() == reflect.Slice || rv.Kind() == reflect.Array {
			for i := 0; i < rv.Len(); i++ {
				if reflect.DeepEqual(rv.Index(i).Interface(), item) {
					return true
				}
			}
		} else if rv.Kind() == reflect.Map {
			key := reflect.ValueOf(toString(item))
			val := rv.MapIndex(key)
			return val.IsValid()
		}
		return false
	}
}

func (ns *CollNS) Index(args ...interface{}) (interface{}, error) {
	if len(args) < 2 {
		return nil, fmt.Errorf("coll.Index requires at least 2 arguments")
	}

	in := args[len(args)-1]
	indexes := args[:len(args)-1]

	current := in
	for _, idx := range indexes {
		var err error
		current, err = indexOne(current, idx)
		if err != nil {
			return nil, err
		}
	}
	return current, nil
}

func indexOne(in, key interface{}) (interface{}, error) {
	switch v := in.(type) {
	case map[string]interface{}:
		k := toString(key)
		val, ok := v[k]
		if !ok {
			return nil, fmt.Errorf("key %q not found", k)
		}
		return val, nil
	case []interface{}:
		i, err := toInt64(key)
		if err != nil {
			return nil, err
		}
		if int(i) < 0 || int(i) >= len(v) {
			return nil, fmt.Errorf("index %d out of range", i)
		}
		return v[i], nil
	default:
		rv := reflect.ValueOf(in)
		switch rv.Kind() {
		case reflect.Map:
			kv := reflect.ValueOf(key)
			val := rv.MapIndex(kv)
			if !val.IsValid() {
				// Try string key
				kv = reflect.ValueOf(toString(key))
				val = rv.MapIndex(kv)
				if !val.IsValid() {
					return nil, fmt.Errorf("key %q not found", key)
				}
			}
			return val.Interface(), nil
		case reflect.Slice, reflect.Array:
			i, err := toInt64(key)
			if err != nil {
				return nil, err
			}
			if int(i) < 0 || int(i) >= rv.Len() {
				return nil, fmt.Errorf("index %d out of range", i)
			}
			return rv.Index(int(i)).Interface(), nil
		}
		return nil, fmt.Errorf("cannot index %T", in)
	}
}

