			return nil, err
		}
		if rest == "" {
			return val, nil
		}
		return evalJQ(rest, val)
	}

	// Keys function
	if expr == "keys" {
		return mapKeys(in)
	}

	// Values function  
	if expr == "values" {
		return mapValues(in)
	}

	// length
	if expr == "length" {
		return jqLength(in)
	}

	// type
	if expr == "type" {
		return jqType(in), nil
	}

	return nil, fmt.Errorf("unsupported jq expression: %s", expr)
}

func jqLength(in interface{}) (int, error) {
	switch v := in.(type) {
	case string:
		return len([]rune(v)), nil
	case []interface{}:
		return len(v), nil
	case map[string]interface{}:
		return len(v), nil
	case nil:
		return 0, nil
	default:
		return 0, nil
	}
