		}
		return m, nil
	}
}

// JSONPath implements simple JSONPath evaluation
func jsonPath(expr string, in interface{}) (interface{}, error) {
	// Simple JSONPath implementation
	// Supports: $, $.key, $[n], $.key1.key2, $.*

	if !strings.HasPrefix(expr, "$") {
		return nil, fmt.Errorf("JSONPath expression must start with $")
	}

	path := expr[1:]
	current := in

	for path != "" {
		if strings.HasPrefix(path, ".") {
			path = path[1:]
			// Extract key
			end := strings.IndexAny(path, ".[")
			var key string
			if end < 0 {
				key = path
				path = ""
			} else {
				key = path[:end]
				path = path[end:]
			}

			if key == "" || key == "*" {
				// Return all values
				if m, ok := current.(map[string]interface{}); ok {
					var result []interface{}
					for _, v := range m {
						result = append(result, v)
					}
					return result, nil
				}
			}

			val, err := indexOne(current, key)
			if err != nil {
				return nil, err
			}
			current = val
		} else if strings.HasPrefix(path, "[") {
			// Array index
			end := strings.Index(path, "]")
			if end < 0 {
				return nil, fmt.Errorf("unterminated [")
			}
			idxStr := path[1:end]
			path = path[end+1:]

			idx, err := toInt64(idxStr)
			if err != nil {
				return nil, err
			}
			val, err := indexOne(current, idx)
			if err != nil {
				return nil, err
			}
			current = val
		} else {
			break
		}
	}

	return current, nil
}

// runJQ implements jq-like functionality
func runJQ(expr string, in interface{}) (interface{}, error) {
	// Simple jq implementation
	// We'll implement basic jq operations
	return evalJQ(expr, in)
}

func evalJQ(expr string, in interface{}) (interface{}, error) {
	expr = strings.TrimSpace(expr)

	// Identity
	if expr == "." {
		return in, nil
	}

	// Field access: .field
	if strings.HasPrefix(expr, ".") {
		field := expr[1:]
		if field == "" {
			return in, nil
		}

		// Check for chained access
		dotIdx := strings.Index(field, ".")
		bracketIdx := strings.Index(field, "[")

		var firstKey string
		var rest string

		if dotIdx >= 0 && (bracketIdx < 0 || dotIdx < bracketIdx) {
			firstKey = field[:dotIdx]
			rest = field[dotIdx:]
		} else if bracketIdx >= 0 {
			firstKey = field[:bracketIdx]
			rest = field[bracketIdx:]
		} else {
			firstKey = field
			rest = ""
		}

		// Optional field access: .field?
		optional := strings.HasSuffix(firstKey, "?")
		if optional {
			firstKey = firstKey[:len(firstKey)-1]
		}

		var val interface{}
		var err error

		if firstKey == "" {
			val = in
		} else {
			val, err = indexOne(in, firstKey)
			if err != nil {
				if optional {
					return nil, nil
				}
				return nil, err
			}
		}

		if rest == "" {
			return val, nil
		}
		return evalJQ(rest, val)
	}

	// Array index: .[n]
	if strings.HasPrefix(expr, "[") {
		end := strings.Index(expr, "]")
		if end < 0 {
			return nil, fmt.Errorf("unterminated [")
		}
		idxStr := expr[1:end]
		rest := expr[end+1:]

		idx, err := toInt64(idxStr)
		if err != nil {
			return nil, err
		}
		val, err := indexOne(in, idx)
		if err != nil {
			return nil, err
		}
		if rest == "" {
			return val, nil
		}
		return evalJQ(rest, val)
	}

	// Keys function
	if expr == "keys" {
		return mapKeys(in)
	}

	// Values function  
	if expr == "values" {
		return mapValues(in)
	}

	// length
	if expr == "length" {
		return jqLength(in)
	}

	// type
	if expr == "type" {
		return jqType(in), nil
	}

	return nil, fmt.Errorf("unsupported jq expression: %s", expr)
}

func jqLength(in interface{}) (int, error) {
	switch v := in.(type) {
	case string:
		return len([]rune(v)), nil
	case []interface{}:
		return len(v), nil
	case map[string]interface{}:
		return len(v), nil
	case nil:
		return 0, nil
	default:
		return 0, nil
	}
}

func jqType(in interface{}) string {
	switch in.(type) {
	case nil:
		return "null"
	case bool:
		return "boolean"
	case float64, float32, int, int64:
		return "number"
	case string:
		return "string"
	case []interface{}:
		return "array"
	case map[string]interface{}:
		return "object"
	default:
		return "other"
	}
}

func addCollFuncs(fm template.FuncMap) {
	ns := &CollNS{}
	fm["dict"] = ns.Dict
	fm["slice"] = ns.Slice
	fm["has"] = ns.Has
	fm["keys"] = ns.Keys
	fm["values"] = ns.Values
	fm["jsonpath"] = ns.JSONPath
	fm["jq"] = ns.JQ
}
