				return nil, err
			}
			return val.Slice(int(i), int(j)).Interface(), nil
		case 3:
			i, err := toInt64(indices[0])
			if err != nil {
				return nil, err
			}
			j, err := toInt64(indices[1])
			if err != nil {
				return nil, err
			}
			k, err := toInt64(indices[2])
			if err != nil {
				return nil, err
			}
			return val.Slice3(int(i), int(j), int(k)).Interface(), nil
		}
	}
	return nil, fmt.Errorf("cannot slice %T", args[0])
}

func (ns *CollNS) Has(in interface{}, item interface{}) bool {
	switch v := in.(type) {
	case map[string]interface{}:
		key := toString(item)
		_, ok := v[key]
		return ok
	case []interface{}:
		for _, e := range v {
			if reflect.DeepEqual(e, item) {
				return true
			}
			if toString(e) == toString(item) {
				return true
			}
		}
		return false
	case []string:
		for _, e := range v {
			if e == toString(item) {
				return true
			}
		}
		return false
	default:
		// Use reflection
		rv := reflect.ValueOf(in)
		if rv.Kind() == reflect.Slice || rv.Kind() == reflect.Array {
			for i := 0; i < rv.Len(); i++ {
				if reflect.DeepEqual(rv.Index(i).Interface(), item) {
					return true
				}
			}
		} else if rv.Kind() == reflect.Map {
			key := reflect.ValueOf(toString(item))
			val := rv.MapIndex(key)
			return val.IsValid()
		}
		return false
	}
}

func (ns *CollNS) Index(args ...interface{}) (interface{}, error) {
	if len(args) < 2 {
		return nil, fmt.Errorf("coll.Index requires at least 2 arguments")
	}

	in := args[len(args)-1]
	indexes := args[:len(args)-1]

	current := in
	for _, idx := range indexes {
		var err error
		current, err = indexOne(current, idx)
		if err != nil {
			return nil, err
		}
	}
	return current, nil
}

func indexOne(in, key interface{}) (interface{}, error) {
	switch v := in.(type) {
	case map[string]interface{}:
		k := toString(key)
		val, ok := v[k]
		if !ok {
			return nil, fmt.Errorf("key %q not found", k)
		}
		return val, nil
	case []interface{}:
		i, err := toInt64(key)
		if err != nil {
			return nil, err
		}
		if int(i) < 0 || int(i) >= len(v) {
			return nil, fmt.Errorf("index %d out of range", i)
		}
		return v[i], nil
	default:
		rv := reflect.ValueOf(in)
		switch rv.Kind() {
		case reflect.Map:
			kv := reflect.ValueOf(key)
			val := rv.MapIndex(kv)
			if !val.IsValid() {
				// Try string key
				kv = reflect.ValueOf(toString(key))
				val = rv.MapIndex(kv)
				if !val.IsValid() {
					return nil, fmt.Errorf("key %q not found", key)
				}
			}
			return val.Interface(), nil
		case reflect.Slice, reflect.Array:
			i, err := toInt64(key)
			if err != nil {
				return nil, err
			}
			if int(i) < 0 || int(i) >= rv.Len() {
				return nil, fmt.Errorf("index %d out of range", i)
			}
			return rv.Index(int(i)).Interface(), nil
		}
		return nil, fmt.Errorf("cannot index %T", in)
	}
}

func (ns *CollNS) JSONPath(expr string, in interface{}) (interface{}, error) {
	return jsonPath(expr, in)
}

func (ns *CollNS) JQ(expr string, in interface{}) (interface{}, error) {
	return runJQ(expr, in)
}

func (ns *CollNS) Keys(args ...interface{}) ([]string, error) {
	var allKeys []string
	for _, in := range args {
		keys, err := mapKeys(in)
		if err != nil {
			return nil, err
		}
		allKeys = append(allKeys, keys...)
	}
	sort.Strings(allKeys)
	return allKeys, nil
}

func (ns *CollNS) Values(args ...interface{}) ([]interface{}, error) {
	var allVals []interface{}
	for _, in := range args {
		vals, err := mapValues(in)
		if err != nil {
			return nil, err
		}
		allVals = append(allVals, vals...)
	}
	return allVals, nil
}

func (ns *CollNS) Append(v interface{}, list interface{}) ([]interface{}, error) {
	result, err := toInterfaceSlice(list)
	if err != nil {
		return nil, err
	}
	return append(result, v), nil
}

func (ns *CollNS) Prepend(v interface{}, list interface{}) ([]interface{}, error) {
	result, err := toInterfaceSlice(list)
	if err != nil {
		return nil, err
	}
	return append([]interface{}{v}, result...), nil
}

func (ns *CollNS) Uniq(list interface{}) ([]interface{}, error) {
	items, err := toInterfaceSlice(list)
	if err != nil {
		return nil, err
	}

	seen := make(map[string]bool)
	var result []interface{}
	for _, item := range items {
		key := toString(item)
		if !seen[key] {
			seen[key] = true
			result = append(result, item)
		}
	}
	return result, nil
}

func (ns *CollNS) Flatten(args ...interface{}) ([]interface{}, error) {
	if len(args) == 1 {
		return flattenList(args[0], -1)
	} else if len(args) == 2 {
		depth, err := toInt64(args[0])
		if err != nil {
			return nil, err
		}
		return flattenList(args[1], int(depth))
	}
	return nil, fmt.Errorf("coll.Flatten requires 1 or 2 arguments")
}

func flattenList(in interface{}, depth int) ([]interface{}, error) {
	items, err := toInterfaceSlice(in)
	if err != nil {
		return nil, err
	}

	var result []interface{}
	for _, item := range items {
		switch v := item.(type) {
		case []interface{}:
			if depth != 0 {
				sub, err := flattenList(v, depth-1)
				if err != nil {
					return nil, err
				}
				result = append(result, sub...)
			} else {
				result = append(result, item)
			}
		default:
			result = append(result, item)
		}
	}
	return result, nil
}

func (ns *CollNS) Reverse(list interface{}) ([]interface{}, error) {
	items, err := toInterfaceSlice(list)
	if err != nil {
		return nil, err
	}
	result := make([]interface{}, len(items))
	for i, item := range items {
		result[len(items)-1-i] = item
	}
	return result, nil
}

func (ns *CollNS) Sort(args ...interface{}) ([]interface{}, error) {
	switch len(args) {
	case 1:
		items, err := toInterfaceSlice(args[0])
		if err != nil {
			return nil, err
		}
		return sortSlice(items, ""), nil
	case 2:
		key := toString(args[0])
		items, err := toInterfaceSlice(args[1])
		if err != nil {
			return nil, err
		}
		return sortSlice(items, key), nil
	}
	return nil, fmt.Errorf("coll.Sort requires 1 or 2 arguments")
}

func sortSlice(items []interface{}, key string) []interface{} {
	result := make([]interface{}, len(items))
	copy(result, items)

	sort.SliceStable(result, func(i, j int) bool {
		var vi, vj interface{}
		if key != "" {
			if m, ok := result[i].(map[string]interface{}); ok {
				vi = m[key]
			}
			if m, ok := result[j].(map[string]interface{}); ok {
				vj = m[key]
			}
		} else {
			vi = result[i]
			vj = result[j]
		}
		return toString(vi) < toString(vj)
	})
	return result
}

func (ns *CollNS) Merge(args ...interface{}) (map[string]interface{}, error) {
	// Merge maps, first map wins (for existing keys)
	result := make(map[string]interface{})

	// Process in reverse order so first arg takes precedence
	for i := len(args) - 1; i >= 0; i-- {
		m, err := toStringMap(args[i])
		if err != nil {
			return nil, err
		}
		for k, v := range m {
			result[k] = v
		}
	}
	return result, nil
}

func (ns *CollNS) Pick(keys interface{}, m interface{}) (map[string]interface{}, error) {
	keyList, err := toStringSlice(keys)
	if err != nil {
		return nil, err
	}

	src, err := toStringMap(m)
	if err != nil {
		return nil, err
	}

	result := make(map[string]interface{})
	for _, k := range keyList {
		if v, ok := src[k]; ok {
			result[k] = v
		}
	}
	return result, nil
}

func (ns *CollNS) Omit(keys interface{}, m interface{}) (map[string]interface{}, error) {
	keyList, err := toStringSlice(keys)
	if err != nil {
		return nil, err
	}

	src, err := toStringMap(m)
	if err != nil {
		return nil, err
	}

	skipSet := make(map[string]bool)
	for _, k := range keyList {
		skipSet[k] = true
	}

	result := make(map[string]interface{})
	for k, v := range src {
		if !skipSet[k] {
			result[k] = v
		}
	}
	return result, nil
}

func (ns *CollNS) Where(key string, value interface{}, list interface{}) ([]interface{}, error) {
	items, err := toInterfaceSlice(list)
	if err != nil {
		return nil, err
	}

	var result []interface{}
	for _, item := range items {
		if m, ok := item.(map[string]interface{}); ok {
			if v, exists := m[key]; exists {
				if fmt.Sprintf("%v", v) == fmt.Sprintf("%v", value) {
					result = append(result, item)
				}
			}
		}
	}
	return result, nil
}

func mapKeys(in interface{}) ([]string, error) {
	switch v := in.(type) {
	case map[string]interface{}:
		keys := make([]string, 0, len(v))
		for k := range v {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		return keys, nil
	default:
		rv := reflect.ValueOf(in)
		if rv.Kind() == reflect.Map {
			var keys []string
			for _, k := range rv.MapKeys() {
				keys = append(keys, toString(k.Interface()))
			}
			sort.Strings(keys)
			return keys, nil
		}
		return nil, fmt.Errorf("cannot get keys of %T", in)
	}
}

func mapValues(in interface{}) ([]interface{}, error) {
	switch v := in.(type) {
	case map[string]interface{}:
		// Get sorted keys to return values in order
		keys := make([]string, 0, len(v))
		for k := range v {
			keys = append(keys, k)
		}
		sort.Strings(keys)

		vals := make([]interface{}, len(keys))
		for i, k := range keys {
			vals[i] = v[k]
		}
		return vals, nil
	default:
		rv := reflect.ValueOf(in)
		if rv.Kind() == reflect.Map {
			var keys []string
			for _, k := range rv.MapKeys() {
				keys = append(keys, toString(k.Interface()))
			}
			sort.Strings(keys)

			result := make([]interface{}, len(keys))
			for i, k := range keys {
				val := rv.MapIndex(reflect.ValueOf(k))
				result[i] = val.Interface()
			}
			return result, nil
		}
		return nil, fmt.Errorf("cannot get values of %T", in)
	}
}

func toInterfaceSlice(in interface{}) ([]interface{}, error) {
	switch v := in.(type) {
	case []interface{}:
		return v, nil
	case []string:
		result := make([]interface{}, len(v))
		for i, s := range v {
			result[i] = s
		}
		return result, nil
	case []int64:
		result := make([]interface{}, len(v))
		for i, n := range v {
			result[i] = n
		}
		return result, nil
	case nil:
		return nil, nil
	default:
		rv := reflect.ValueOf(in)
		if rv.Kind() == reflect.Slice || rv.Kind() == reflect.Array {
			result := make([]interface{}, rv.Len())
			for i := 0; i < rv.Len(); i++ {
				result[i] = rv.Index(i).Interface()
			}
			return result, nil
		}
		return nil, fmt.Errorf("cannot convert %T to []interface{}", in)
	}
}

func toStringMap(in interface{}) (map[string]interface{}, error) {
	switch v := in.(type) {
	case map[string]interface{}:
		return v, nil
	default:
		// Try JSON round-trip
		b, err := json.Marshal(in)
		if err != nil {
			return nil, err
		}
		var m map[string]interface{}
		if err := json.Unmarshal(b, &m); err != nil {
			return nil, fmt.Errorf("cannot convert %T to map[string]interface{}", in)
		}
		return m, nil
	}
}

// JSONPath implements simple JSONPath evaluation
func jsonPath(expr string, in interface{}) (interface{}, error) {
	// Simple JSONPath implementation
	// Supports: $, $.key, $[n], $.key1.key2, $.*

	if !strings.HasPrefix(expr, "$") {
		return nil, fmt.Errorf("JSONPath expression must start with $")
	}

	path := expr[1:]
	current := in

	for path != "" {
		if strings.HasPrefix(path, ".") {
			path = path[1:]
			// Extract key
			end := strings.IndexAny(path, ".[")
			var key string
			if end < 0 {
				key = path
				path = ""
			} else {
				key = path[:end]
				path = path[end:]
			}

			if key == "" || key == "*" {
				// Return all values
				if m, ok := current.(map[string]interface{}); ok {
					var result []interface{}
					for _, v := range m {
						result = append(result, v)
					}
					return result, nil
				}
			}

			val, err := indexOne(current, key)
			if err != nil {
				return nil, err
			}
			current = val
		} else if strings.HasPrefix(path, "[") {
			// Array index
			end := strings.Index(path, "]")
			if end < 0 {
				return nil, fmt.Errorf("unterminated [")
			}
			idxStr := path[1:end]
			path = path[end+1:]

			idx, err := toInt64(idxStr)
			if err != nil {
				return nil, err
			}
			val, err := indexOne(current, idx)
			if err != nil {
				return nil, err
			}
			current = val
		} else {
			break
		}
	}

	return current, nil
}

// runJQ implements jq-like functionality
func runJQ(expr string, in interface{}) (interface{}, error) {
	// Simple jq implementation
	// We'll implement basic jq operations
	return evalJQ(expr, in)
}

func evalJQ(expr string, in interface{}) (interface{}, error) {
	expr = strings.TrimSpace(expr)

	// Identity
	if expr == "." {
		return in, nil
	}

	// Field access: .field
	if strings.HasPrefix(expr, ".") {
		field := expr[1:]
		if field == "" {
			return in, nil
		}

		// Check for chained access
		dotIdx := strings.Index(field, ".")
		bracketIdx := strings.Index(field, "[")

		var firstKey string
		var rest string

		if dotIdx >= 0 && (bracketIdx < 0 || dotIdx < bracketIdx) {
			firstKey = field[:dotIdx]
			rest = field[dotIdx:]
		} else if bracketIdx >= 0 {
			firstKey = field[:bracketIdx]
			rest = field[bracketIdx:]
		} else {
			firstKey = field
			rest = ""
		}

		// Optional field access: .field?
		optional := strings.HasSuffix(firstKey, "?")
		if optional {
			firstKey = firstKey[:len(firstKey)-1]
		}

		var val interface{}
		var err error

		if firstKey == "" {
			val = in
		} else {
			val, err = indexOne(in, firstKey)
			if err != nil {
				if optional {
					return nil, nil
				}
				return nil, err
			}
		}

		if rest == "" {
			return val, nil
		}
		return evalJQ(rest, val)
	}

	// Array index: .[n]
	if strings.HasPrefix(expr, "[") {
		end := strings.Index(expr, "]")
		if end < 0 {
			return nil, fmt.Errorf("unterminated [")
		}
		idxStr := expr[1:end]
		rest := expr[end+1:]

		idx, err := toInt64(idxStr)
		if err != nil {
			return nil, err
		}
		val, err := indexOne(in, idx)
		if err != nil {
			return nil, err
		}
		if rest == "" {
			return val, nil
		}
		return evalJQ(rest, val)
	}

	// Keys function
	if expr == "keys" {
		return mapKeys(in)
	}

	// Values function  
	if expr == "values" {
		return mapValues(in)
	}

	// length
	if expr == "length" {
		return jqLength(in)
	}

	// type
	if expr == "type" {
		return jqType(in), nil
	}

	return nil, fmt.Errorf("unsupported jq expression: %s", expr)
}

func jqLength(in interface{}) (int, error) {
	switch v := in.(type) {
	case string:
		return len([]rune(v)), nil
	case []interface{}:
		return len(v), nil
	case map[string]interface{}:
		return len(v), nil
	case nil:
		return 0, nil
	default:
		return 0, nil
	}
}

func jqType(in interface{}) string {
	switch in.(type) {
	case nil:
		return "null"
	case bool:
		return "boolean"
	case float64, float32, int, int64:
		return "number"
	case string:
		return "string"
	case []interface{}:
		return "array"
	case map[string]interface{}:
		return "object"
	default:
		return "other"
	}
}

