func (ns *CollNS) Dict(args ...interface{}) map[string]interface{} {
	m := make(map[string]interface{})
	for i := 0; i+1 < len(args); i += 2 {
		k := toString(args[i])
		m[k] = args[i+1]
	}
	// If odd number of args, last key gets empty string
	if len(args)%2 != 0 {
