// JSON parsing
func parseJSON(in string) (interface{}, error) {
	in = strings.TrimSpace(in)
	var result interface{}
	if err := json.Unmarshal([]byte(in), &result); err != nil {
		return nil, fmt.Errorf("parsing JSON: %w", err)
	}
	return convertJSON(result), nil
}

// convertJSON converts JSON numbers to int64 when appropriate
func convertJSON(v interface{}) interface{} {
	switch val := v.(type) {
	case map[string]interface{}:
		result := make(map[string]interface{}, len(val))
		for k, v := range val {
			result[k] = convertJSON(v)
		}
		return result
	case []interface{}:
		result := make([]interface{}, len(val))
		for i, v := range val {
			result[i] = convertJSON(v)
		}
		return result
	case float64:
		// Return as int64 if it's a whole number
		if val == float64(int64(val)) && val >= -1e15 && val <= 1e15 {
			return int64(val)
		}
		return val
	default:
		return v
	}
}

func parseJSONArray(in string) ([]interface{}, error) {
	in = strings.TrimSpace(in)
	var result []interface{}
	if err := json.Unmarshal([]byte(in), &result); err != nil {
		return nil, fmt.Errorf("parsing JSON array: %w", err)
	}
	converted := convertJSON(result)
	if arr, ok := converted.([]interface{}); ok {
		return arr, nil
	}
	return result, nil
}

// CSV parsing
func parseCSV(sep, in string) ([][]string, error) {
	r := csv.NewReader(strings.NewReader(in))
	if sep != "" && sep != "," {
		r.Comma = []rune(sep)[0]
	}
	return r.ReadAll()
}

func parseCSVByRow(sep, in string) ([]map[string]string, error) {
	rows, err := parseCSV(sep, in)
	if err != nil {
		return nil, err
	}
	if len(rows) == 0 {
		return nil, nil
	}

	headers := rows[0]
	var result []map[string]string
	for _, row := range rows[1:] {
		m := make(map[string]string)
		for i, h := range headers {
			if i < len(row) {
				m[h] = row[i]
			}
		}
		result = append(result, m)
	}
	return result, nil
}

func parseCSVByColumn(sep, in string) (map[string][]string, error) {
	rows, err := parseCSV(sep, in)
	if err != nil {
		return nil, err
	}
	if len(rows) == 0 {
		return nil, nil
	}

	headers := rows[0]
	result := make(map[string][]string)
	for _, h := range headers {
		result[h] = nil
	}

	for _, row := range rows[1:] {
		for i, h := range headers {
			if i < len(row) {
				result[h] = append(result[h], row[i])
			}
		}
	}
	return result, nil
}

func marshalCSV(sep string, in interface{}) (string, error) {
	var rows [][]string

	switch v := in.(type) {
	case [][]string:
		rows = v
	case [][]interface{}:
		for _, row := range v {
			strRow := make([]string, len(row))
			for i, cell := range row {
				strRow[i] = fmt.Sprintf("%v", cell)
			}
			rows = append(rows, strRow)
		}
	case []interface{}:
		for _, row := range v {
			switch r := row.(type) {
			case []string:
				rows = append(rows, r)
			case []interface{}:
				strRow := make([]string, len(r))
				for i, cell := range r {
					strRow[i] = fmt.Sprintf("%v", cell)
				}
				rows = append(rows, strRow)
			default:
				rows = append(rows, []string{fmt.Sprintf("%v", r)})
			}
		}
	default:
		return "", fmt.Errorf("cannot convert %T to CSV", in)
	}

	var buf bytes.Buffer
	w := csv.NewWriter(&buf)
	if sep != "" && sep != "," {
		w.Comma = []rune(sep)[0]
	}
	if err := w.WriteAll(rows); err != nil {
		return "", err
	}
	return buf.String(), nil
}

// parse env file format
func parseEnvFile(content string) (map[string]string, error) {
	result := make(map[string]string)
	lines := strings.Split(content, "\n")

	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		// Strip "export " prefix
		line = strings.TrimPrefix(line, "export ")

		eqIdx := strings.IndexByte(line, '=')
		if eqIdx < 0 {
			continue
		}

		key := strings.TrimSpace(line[:eqIdx])
		value := strings.TrimSpace(line[eqIdx+1:])

		// Unquote value
		if len(value) >= 2 {
			if (value[0] == '"' && value[len(value)-1] == '"') ||
				(value[0] == '\'' && value[len(value)-1] == '\'') {
				inner := value[1 : len(value)-1]
				if value[0] == '"' {
					// Process escape sequences
					inner = processEscapes(inner)
				}
				value = inner
			}
		}

		result[key] = value
	}

	return result, nil
}

func processEscapes(s string) string {
	result := strings.Builder{}
	i := 0
	for i < len(s) {
		if s[i] == '\\' && i+1 < len(s) {
			switch s[i+1] {
			case 'n':
				result.WriteByte('\n')
			case 't':
				result.WriteByte('\t')
			case 'r':
				result.WriteByte('\r')
			case '\\':
				result.WriteByte('\\')
			case '"':
				result.WriteByte('"')
			default:
				result.WriteByte(s[i])
				result.WriteByte(s[i+1])
			}
			i += 2
		} else {
			result.WriteByte(s[i])
			i++
		}
	}
	return result.String()
}

