func decryptAES(key []byte, keyBits int, ciphertext []byte) ([]byte, error) {
	keyLen := keyBits / 8
	paddedKey := padKey(key, keyLen)

	block, err := aes.NewCipher(paddedKey)
	if err != nil {
		return nil, err
	}

	if len(ciphertext) < aes.BlockSize {
		return nil, fmt.Errorf("ciphertext too short")
	}

	iv := ciphertext[:aes.BlockSize]
	ciphertext = ciphertext[aes.BlockSize:]

	mode := cipher.NewCBCDecrypter(block, iv)
	mode.CryptBlocks(ciphertext, ciphertext)

	// Unpad PKCS7
	if len(ciphertext) == 0 {
		return nil, fmt.Errorf("empty ciphertext")
	}
	padLen := int(ciphertext[len(ciphertext)-1])
	if padLen > len(ciphertext) || padLen == 0 {
		return nil, fmt.Errorf("invalid padding")
	}
	return ciphertext[:len(ciphertext)-padLen], nil
}

func encryptAES(key []byte, keyBits int, plaintext []byte) ([]byte, error) {
	keyLen := keyBits / 8
	paddedKey := padKey(key, keyLen)

	block, err := aes.NewCipher(paddedKey)
	if err != nil {
		return nil, err
	}

	// PKCS7 pad
	padLen := aes.BlockSize - len(plaintext)%aes.BlockSize
	padded := make([]byte, len(plaintext)+padLen)
	copy(padded, plaintext)
	for i := len(plaintext); i < len(padded); i++ {
		padded[i] = byte(padLen)
	}

	ciphertext := make([]byte, aes.BlockSize+len(padded))
	iv := ciphertext[:aes.BlockSize]
	if _, err := io.ReadFull(rand.Reader, iv); err != nil {
		return nil, err
	}

	mode := cipher.NewCBCEncrypter(block, iv)
	mode.CryptBlocks(ciphertext[aes.BlockSize:], padded)

	return ciphertext, nil
}

func padKey(key []byte, size int) []byte {
	result := make([]byte, size)
	// Hash the key if it doesn't fit
	if len(key) != size {
		h := sha256.Sum256(key)
		copy(result, h[:])
	} else {
		copy(result, key)
	}
	return result
}

// PBKDF2 key derivation
func pbkdf2Key(password, salt []byte, iter, keyLen int, h func() interface{ io.Writer; Sum(b []byte) []byte }) []byte {
	prf := hmac.New(func() interface {
		io.Writer
		Sum(b []byte) []byte
	} {
		return h()
	}, password)
	hashLen := prf.Size()
	numBlocks := (keyLen + hashLen - 1) / hashLen

	var buf [4]byte
	dk := make([]byte, 0, numBlocks*hashLen)
	U := make([]byte, hashLen)
	for block := 1; block <= numBlocks; block++ {
		prf.Reset()
		prf.Write(salt)
		buf[0] = byte(block >> 24)
		buf[1] = byte(block >> 16)
		buf[2] = byte(block >> 8)
		buf[3] = byte(block)
		prf.Write(buf[:4])
		dk = prf.Sum(dk)
		T := dk[len(dk)-hashLen:]
		copy(U, T)
		for n := 2; n <= iter; n++ {
			prf.Reset()
			prf.Write(U)
			U = U[:0]
			U = prf.Sum(U)
			for x := range U {
				T[x] ^= U[x]
			}
		}
	}
	return dk[:keyLen]
}

