		return nil, err
	}

	mode := cipher.NewCBCEncrypter(block, iv)
	mode.CryptBlocks(ciphertext[aes.BlockSize:], padded)

	return ciphertext, nil
}

func padKey(key []byte, size int) []byte {
	result := make([]byte, size)
	// Hash the key if it doesn't fit
	if len(key) != size {
		h := sha256.Sum256(key)
		copy(result, h[:])
	} else {
		copy(result, key)
	}
	return result
}

// PBKDF2 key derivation
func pbkdf2Key(password, salt []byte, iter, keyLen int, h func() interface{ io.Writer; Sum(b []byte) []byte }) []byte {
	prf := hmac.New(func() interface {
		io.Writer
		Sum(b []byte) []byte
	} {
		return h()
	}, password)
	hashLen := prf.Size()
	numBlocks := (keyLen + hashLen - 1) / hashLen

	var buf [4]byte
	dk := make([]byte, 0, numBlocks*hashLen)
	U := make([]byte, hashLen)
	for block := 1; block <= numBlocks; block++ {
		prf.Reset()
		prf.Write(salt)
		buf[0] = byte(block >> 24)
		buf[1] = byte(block >> 16)
		buf[2] = byte(block >> 8)
		buf[3] = byte(block)
		prf.Write(buf[:4])
		dk = prf.Sum(dk)
		T := dk[len(dk)-hashLen:]
		copy(U, T)
		for n := 2; n <= iter; n++ {
			prf.Reset()
			prf.Write(U)
			U = U[:0]
			U = prf.Sum(U)
			for x := range U {
				T[x] ^= U[x]
			}
		}
	}
	return dk[:keyLen]
}

