package main

import (
	"fmt"
	"math/rand"
	"regexp"
	"text/template"
	"unicode"
)

// RandomNS is the random namespace
type RandomNS struct{}

const printableASCII = " !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~"
const alphaChars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
const alphaNumChars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
const defaultStringChars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.-"

func (ns *RandomNS) ASCII(count int) (string, error) {
	if count < 0 {
		return "", fmt.Errorf("count must be >= 0")
	}
	result := make([]byte, count)
	for i := range result {
		result[i] = printableASCII[rand.Intn(len(printableASCII))]
	}
	return string(result), nil
}

func (ns *RandomNS) Alpha(count int) (string, error) {
	if count < 0 {
		return "", fmt.Errorf("count must be >= 0")
	}
	result := make([]byte, count)
	for i := range result {
		result[i] = alphaChars[rand.Intn(len(alphaChars))]
	}
	return string(result), nil
}

func (ns *RandomNS) AlphaNum(count int) (string, error) {
	if count < 0 {
		return "", fmt.Errorf("count must be >= 0")
	}
	result := make([]byte, count)
	for i := range result {
		result[i] = alphaNumChars[rand.Intn(len(alphaNumChars))]
	}
	return string(result), nil
}

func (ns *RandomNS) String(args ...interface{}) (string, error) {
	if len(args) == 0 {
		return "", fmt.Errorf("random.String requires at least 1 argument")
	}

	count, err := toInt64(args[0])
	if err != nil {
		return "", err
	}

	if len(args) == 1 {
		// Default charset
		return randomFromChars(int(count), defaultStringChars), nil
	}

	if len(args) == 2 {
		// regex or charset
		s := fmt.Sprintf("%v", args[1])
		return randomFromRegex(int(count), s)
	}

	if len(args) == 3 {
		// range: lower upper
		lower := fmt.Sprintf("%v", args[1])
		upper := fmt.Sprintf("%v", args[2])
		return randomFromRange(int(count), lower, upper)
	}

	return "", fmt.Errorf("random.String requires 1, 2, or 3 arguments")
}

func randomFromChars(count int, chars string) string {
	runes := []rune(chars)
	result := make([]rune, count)
	for i := range result {
		result[i] = runes[rand.Intn(len(runes))]
	}
	return string(result)
}

func randomFromRegex(count int, pattern string) (string, error) {
	// Build a character set from the regex pattern
	re, err := regexp.Compile(pattern)
	if err != nil {
		return "", fmt.Errorf("invalid regex: %w", err)
	}

	// Generate all printable Unicode characters that match the pattern
	var chars []rune
	for r := rune(0x20); r <= 0x10FFFF; r++ {
		if r >= 0xD800 && r <= 0xDFFF {
			continue // skip surrogates
		}
		if !unicode.IsPrint(r) {
			continue
		}
		if re.MatchString(string(r)) {
			chars = append(chars, r)
		}
		if len(chars) > 10000 {
			break
		}
	}

	if len(chars) == 0 {
		return "", fmt.Errorf("no characters match pattern %q", pattern)
	}

	result := make([]rune, count)
	for i := range result {
		result[i] = chars[rand.Intn(len(chars))]
	}
	return string(result), nil
}

func randomFromRange(count int, lower, upper string) (string, error) {
	// Parse lower and upper as runes
	var lowerRune, upperRune rune

	if len([]rune(lower)) == 1 {
		lowerRune = []rune(lower)[0]
	} else {
		// Try as a number
		n, err := toInt64(lower)
		if err != nil {
			return "", fmt.Errorf("invalid lower bound: %s", lower)
		}
		lowerRune = rune(n)
	}

	if len([]rune(upper)) == 1 {
		upperRune = []rune(upper)[0]
	} else {
		n, err := toInt64(upper)
		if err != nil {
			return "", fmt.Errorf("invalid upper bound: %s", upper)
		}
		upperRune = rune(n)
	}

	// Build list of printable chars in range
	var chars []rune
	for r := lowerRune; r <= upperRune; r++ {
		if unicode.IsPrint(r) {
			chars = append(chars, r)
		}
	}

	if len(chars) == 0 {
		return "", fmt.Errorf("no printable characters in range %q to %q", lower, upper)
	}

	result := make([]rune, count)
	for i := range result {
		result[i] = chars[rand.Intn(len(chars))]
	}
	return string(result), nil
}

