package main

import (
	"fmt"
	"os"
	"text/template"
)

// FileNS is the file namespace
type FileNS struct{}

func (ns *FileNS) Exists(path string) bool {
	_, err := os.Stat(path)
	return err == nil
}

func (ns *FileNS) IsDir(path string) bool {
	fi, err := os.Stat(path)
	if err != nil {
		return false
	}
	return fi.IsDir()
}

func (ns *FileNS) Read(path string) (string, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return "", fmt.Errorf("file.Read: %w", err)
	}
	return string(data), nil
}

func (ns *FileNS) ReadDir(path string) ([]string, error) {
	entries, err := os.ReadDir(path)
	if err != nil {
		return nil, fmt.Errorf("file.ReadDir: %w", err)
	}
	names := make([]string, len(entries))
	for i, e := range entries {
		names[i] = e.Name()
	}
	return names, nil
}

