func (ns *RegexpNS) Find(expr string, in string) (string, error) {
	re, err := regexp.Compile(expr)
	if err != nil {
		return "", fmt.Errorf("invalid regexp: %w", err)
	}
	return re.FindString(in), nil
}

func (ns *RegexpNS) FindAll(args ...interface{}) ([]string, error) {
	// regexp.FindAll expression [n] input
	switch len(args) {
	case 2:
		expr := fmt.Sprintf("%v", args[0])
		in := fmt.Sprintf("%v", args[1])
		re, err := regexp.Compile(expr)
		if err != nil {
			return nil, fmt.Errorf("invalid regexp: %w", err)
		}
		return re.FindAllString(in, -1), nil
	case 3:
		expr := fmt.Sprintf("%v", args[0])
		n, err := toInt64(args[1])
		if err != nil {
			return nil, fmt.Errorf("n must be an integer: %w", err)
		}
		in := fmt.Sprintf("%v", args[2])
		re, err := regexp.Compile(expr)
		if err != nil {
			return nil, fmt.Errorf("invalid regexp: %w", err)
		}
		return re.FindAllString(in, int(n)), nil
	}
	return nil, fmt.Errorf("regexp.FindAll requires 2 or 3 arguments")
