		if !toBoolValue(args[1]) {
			return "", fmt.Errorf("assertion failed: %v", args[0])
		}
	default:
		return "", fmt.Errorf("test.Assert requires 1 or 2 arguments")
	}
	return "", nil
}

func (ns *TestNS) Fail(args ...interface{}) (string, error) {
	if len(args) == 0 {
		return "", fmt.Errorf("template generation failed")
	}
	return "", fmt.Errorf("template generation failed: %v", args[0])
}

func (ns *TestNS) IsKind(kind string, value interface{}) bool {
	return checkKind(kind, value)
}

func (ns *TestNS) Kind(value interface{}) string {
	return getKind(value)
}

