	// required [message] value
	switch len(args) {
	case 1:
		v := args[0]
		if isEmpty(v) {
			return nil, fmt.Errorf("required value is empty")
		}
		return v, nil
	case 2:
		msg := fmt.Sprintf("%v", args[0])
		v := args[1]
		if isEmpty(v) {
			return nil, fmt.Errorf("%s", msg)
		}
		return v, nil
	default:
		return nil, fmt.Errorf("test.Required requires 1 or 2 arguments")
	}
}

