	case uint, uint8, uint16, uint32, uint64:
		return toUint64Must(v) != 0
	case float32, float64:
		return toFloat64Must(v) != 0
	case string:
		conv := &ConvNS{}
		return conv.ToBool(val)
	case nil:
		return false
	}
	return true
}

