	case reflect.Slice, reflect.Array:
		return "slice"
	case reflect.Map:
		return "map"
	case reflect.Ptr:
		return "ptr"
	case reflect.Invalid:
		return "invalid"
	default:
		return rv.Kind().String()
	}
}

