	all, err := ns.GetAllInterfaces()
	if err != nil {
		return nil, err
	}

	var result []*IfAddr
	for _, a := range all {
		if !a.IP.IsLoopback() && !a.IP.IsMulticast() {
			result = append(result, a)
		}
	}
	return result, nil
}

