package main

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
	"text/template"
)

// SemverNS is the semver namespace
type SemverNS struct{}

// SemVer represents a semantic version
type SemVer struct {
	Major      int64
	Minor      int64
	Patch      int64
	Prerelease string
	Metadata   string
	original   string
}

func (v *SemVer) String() string {
	result := fmt.Sprintf("%d.%d.%d", v.Major, v.Minor, v.Patch)
	if v.Prerelease != "" {
		result += "-" + v.Prerelease
	}
	if v.Metadata != "" {
		result += "+" + v.Metadata
	}
	return result
}

func (v *SemVer) SetPrerelease(pre string) *SemVer {
	return &SemVer{
		Major:      v.Major,
		Minor:      v.Minor,
		Patch:      v.Patch,
		Prerelease: pre,
		Metadata:   v.Metadata,
	}
}

func (v *SemVer) SetMetadata(meta string) *SemVer {
	return &SemVer{
		Major:      v.Major,
		Minor:      v.Minor,
		Patch:      v.Patch,
		Prerelease: v.Prerelease,
		Metadata:   meta,
	}
}

func (v *SemVer) GreaterThan(other *SemVer) bool {
	return semverCompare(v, other) > 0
}

func (v *SemVer) LessThan(other *SemVer) bool {
	return semverCompare(v, other) < 0
}

func (v *SemVer) Equal(other *SemVer) bool {
	return semverCompare(v, other) == 0
}

func (ns *SemverNS) Semver(s string) (*SemVer, error) {
	return parseSemVer(s)
}

func (ns *SemverNS) CheckConstraint(constraint, version string) (bool, error) {
	v, err := parseSemVer(version)
	if err != nil {
		return false, err
	}
	return checkSemverConstraint(constraint, v)
}

func parseSemVer(s string) (*SemVer, error) {
	// Strip 'v' prefix
	original := s
	s = strings.TrimPrefix(s, "v")

	// Regex for semver
	re := regexp.MustCompile(`^(\d+)\.(\d+)\.(\d+)(?:-([a-zA-Z0-9._\-]+))?(?:\+([a-zA-Z0-9._\-]+))?$`)
	m := re.FindStringSubmatch(s)
	if m == nil {
		// Try just major.minor
		re2 := regexp.MustCompile(`^(\d+)\.(\d+)(?:-([a-zA-Z0-9._\-]+))?(?:\+([a-zA-Z0-9._\-]+))?$`)
		m2 := re2.FindStringSubmatch(s)
		if m2 != nil {
			major, _ := strconv.ParseInt(m2[1], 10, 64)
			minor, _ := strconv.ParseInt(m2[2], 10, 64)
			return &SemVer{Major: major, Minor: minor, Patch: 0, Prerelease: m2[3], Metadata: m2[4], original: original}, nil
		}
		// Try just major
		re3 := regexp.MustCompile(`^(\d+)(?:-([a-zA-Z0-9._\-]+))?(?:\+([a-zA-Z0-9._\-]+))?$`)
		m3 := re3.FindStringSubmatch(s)
		if m3 != nil {
			major, _ := strconv.ParseInt(m3[1], 10, 64)
			return &SemVer{Major: major, Minor: 0, Patch: 0, Prerelease: m3[2], Metadata: m3[3], original: original}, nil
		}
		return nil, fmt.Errorf("invalid semver: %s", original)
	}

	major, _ := strconv.ParseInt(m[1], 10, 64)
	minor, _ := strconv.ParseInt(m[2], 10, 64)
	patch, _ := strconv.ParseInt(m[3], 10, 64)

	return &SemVer{
		Major:      major,
		Minor:      minor,
		Patch:      patch,
		Prerelease: m[4],
		Metadata:   m[5],
		original:   original,
	}, nil
}

func semverCompare(a, b *SemVer) int {
	if a.Major != b.Major {
		if a.Major > b.Major {
			return 1
		}
		return -1
	}
	if a.Minor != b.Minor {
		if a.Minor > b.Minor {
			return 1
		}
		return -1
	}
	if a.Patch != b.Patch {
		if a.Patch > b.Patch {
			return 1
		}
		return -1
	}

	// Pre-release comparison
	if a.Prerelease == "" && b.Prerelease != "" {
		return 1 // No pre-release > pre-release
	}
	if a.Prerelease != "" && b.Prerelease == "" {
		return -1
	}
	if a.Prerelease != b.Prerelease {
		return strings.Compare(a.Prerelease, b.Prerelease)
	}
	return 0
}

// checkSemverConstraint checks if a version satisfies a constraint
func checkSemverConstraint(constraint string, v *SemVer) (bool, error) {
	// Parse comma-separated constraints (AND)
	parts := strings.Split(constraint, ",")
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if !checkSingleConstraint(part, v) {
			return false, nil
		}
	}
	return true, nil
}

func checkSingleConstraint(constraint string, v *SemVer) bool {
	constraint = strings.TrimSpace(constraint)

	var op string
	var versionStr string

	// Parse operator
	if strings.HasPrefix(constraint, ">=") {
		op = ">="
		versionStr = strings.TrimSpace(constraint[2:])
	} else if strings.HasPrefix(constraint, "<=") {
		op = "<="
		versionStr = strings.TrimSpace(constraint[2:])
	} else if strings.HasPrefix(constraint, ">") {
		op = ">"
		versionStr = strings.TrimSpace(constraint[1:])
	} else if strings.HasPrefix(constraint, "<") {
		op = "<"
		versionStr = strings.TrimSpace(constraint[1:])
	} else if strings.HasPrefix(constraint, "!=") {
		op = "!="
		versionStr = strings.TrimSpace(constraint[2:])
	} else if strings.HasPrefix(constraint, "~>") {
		op = "~>"
		versionStr = strings.TrimSpace(constraint[2:])
	} else if strings.HasPrefix(constraint, "~") {
		op = "~"
		versionStr = strings.TrimSpace(constraint[1:])
	} else if strings.HasPrefix(constraint, "^") {
		op = "^"
		versionStr = strings.TrimSpace(constraint[1:])
	} else {
		op = "="
		versionStr = constraint
	}

	target, err := parseSemVer(versionStr)
	if err != nil {
		return false
	}

	cmp := semverCompare(v, target)

	switch op {
	case "=", "==":
		return cmp == 0
	case "!=":
		return cmp != 0
	case ">":
		return cmp > 0
	case ">=":
		return cmp >= 0
	case "<":
		return cmp < 0
	case "<=":
		return cmp <= 0
	case "~", "~>":
		// Compatible release: >= target, < next minor
		if cmp < 0 {
			return false
		}
		// Check upper bound
		next := &SemVer{Major: target.Major, Minor: target.Minor + 1, Patch: 0}
		return semverCompare(v, next) < 0
	case "^":
		// Compatible with: same major, >= target
		if v.Major != target.Major {
			return false
		}
		return cmp >= 0
	}
	return false
}

