func (ns *AWSNS) EC2Meta(key string, def ...string) (string, error) {
	return awsMeta("http://169.254.169.254/latest/meta-data/"+key, def...)
}

func (ns *AWSNS) EC2Dynamic(key string, def ...string) (string, error) {
	return awsMeta("http://169.254.169.254/latest/dynamic/"+key, def...)
}

func (ns *AWSNS) EC2Tag(tag string, def ...string) (string, error) {
	return awsMeta("tag/"+tag, def...)
}

func (ns *AWSNS) EC2Region(def ...string) (string, error) {
	return awsMeta("placement/region", def...)
}

func awsMeta(url string, def ...string) (string, error) {
	timeout := 500 * time.Millisecond
	if v := getenvWithFileFallback("AWS_TIMEOUT"); v != "" {
		if n, err := toInt64(v); err == nil {
			timeout = time.Duration(n) * time.Millisecond
		}
	}

	ctx, cancel := context.WithTimeout(context.Background(), timeout)
	defer cancel()

	req, err := http.NewRequestWithContext(ctx, "GET", url, nil)
	if err != nil {
		if len(def) > 0 {
			return def[0], nil
		}
		return "", err
	}

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		if len(def) > 0 {
			return def[0], nil
		}
		return "", err
	}
	defer resp.Body.Close()

	data, err := io.ReadAll(resp.Body)
	if err != nil {
		if len(def) > 0 {
			return def[0], nil
		}
		return "", err
	}

	return strings.TrimSpace(string(data)), nil
}

// GCPNS is the GCP namespace
type GCPNS struct{}

