package main

import (
	"fmt"
	"strconv"
	"strings"
)

// parseSimpleYAML parses a YAML document
func parseSimpleYAML(content string) (map[string]interface{}, error) {
	result, err := parseYAML(content)
	if err != nil {
		return nil, err
	}
	if m, ok := result.(map[string]interface{}); ok {
		return m, nil
	}
	return nil, fmt.Errorf("expected YAML map, got %T", result)
}

// parseYAML parses a YAML string
func parseYAML(content string) (interface{}, error) {
	p := &yamlParser{input: content, line: 1}
	return p.parseDocument()
}

type yamlParser struct {
	input string
	pos   int
	line  int
	col   int
}

func (p *yamlParser) parseDocument() (interface{}, error) {
	// Skip document markers
	p.skipDocumentMarkers()
	p.skipEmptyLines()

	if p.pos >= len(p.input) {
		return nil, nil
	}

	return p.parseValue(0)
}

func (p *yamlParser) skipDocumentMarkers() {
	for p.pos < len(p.input) {
		line := p.currentLine()
		if line == "---" || line == "..." {
			p.skipLine()
		} else {
			break
		}
	}
}

func (p *yamlParser) currentLine() string {
	start := p.pos
	end := strings.IndexByte(p.input[p.pos:], '\n')
	if end < 0 {
		return strings.TrimRight(p.input[p.pos:], " \t")
	}
	return strings.TrimRight(p.input[p.pos:p.pos+end], " \t")
}

func (p *yamlParser) skipLine() {
	for p.pos < len(p.input) && p.input[p.pos] != '\n' {
		p.pos++
	}
	if p.pos < len(p.input) {
		p.pos++ // skip \n
		p.line++
	}
}

func (p *yamlParser) skipEmptyLines() {
	for p.pos < len(p.input) {
		line := p.currentLine()
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			p.skipLine()
		} else {
			break
		}
	}
}

func (p *yamlParser) currentIndent() int {
	count := 0
	for p.pos+count < len(p.input) && p.input[p.pos+count] == ' ' {
		count++
	}
	return count
}

func (p *yamlParser) parseValue(minIndent int) (interface{}, error) {
	p.skipEmptyLines()

	if p.pos >= len(p.input) {
		return nil, nil
	}

	indent := p.currentIndent()
	if indent < minIndent {
		return nil, nil
	}

	// Check what kind of value this is
	ch := p.input[p.pos+indent]

	// Check for sequence
	if ch == '-' && (p.pos+indent+1 >= len(p.input) || p.input[p.pos+indent+1] == ' ' || p.input[p.pos+indent+1] == '\n') {
		return p.parseSequence(indent)
	}

	// Check for block scalar
	if ch == '|' || ch == '>' {
		return p.parseBlockScalar(indent, ch)
	}

	// Try to parse as map
	line := p.currentLine()
	trimmed := strings.TrimSpace(line)
	if colon := findMapColon(trimmed); colon >= 0 {
		// Check if there's a value on the same line
		key := trimmed[:colon]
		if isValidMapKey(key) {
			return p.parseMapping(indent)
		}
	}

	// Parse as scalar
	return p.parseScalar(indent)
}

func findMapColon(s string) int {
	// Find ': ' or ':' at end of string (not inside quotes)
	inSingleQuote := false
	inDoubleQuote := false

	for i := 0; i < len(s); i++ {
		ch := s[i]
		if ch == '\'' && !inDoubleQuote {
			inSingleQuote = !inSingleQuote
		} else if ch == '"' && !inSingleQuote {
			inDoubleQuote = !inDoubleQuote
		} else if ch == ':' && !inSingleQuote && !inDoubleQuote {
			if i+1 == len(s) || s[i+1] == ' ' || s[i+1] == '\n' || s[i+1] == '\t' {
				return i
			}
		}
	}
	return -1
}

func isValidMapKey(key string) bool {
	if len(key) == 0 {
		return false
	}
	// A key can be quoted or unquoted
	if key[0] == '"' || key[0] == '\'' {
		return true
	}
	// Can't start with { or [
	if key[0] == '{' || key[0] == '[' {
		return false
	}
	return true
}

func (p *yamlParser) parseMapping(baseIndent int) (map[string]interface{}, error) {
	result := make(map[string]interface{})

	for p.pos < len(p.input) {
		p.skipEmptyLines()
		if p.pos >= len(p.input) {
			break
		}

		indent := p.currentIndent()
		if indent < baseIndent {
			break
		}
		if indent > baseIndent {
			break
		}

		// Parse key: value
		line := p.currentLine()
		trimmed := strings.TrimSpace(line)

		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			p.skipLine()
			continue
		}

		// Check for sequence item at this level
		if strings.HasPrefix(trimmed, "- ") || trimmed == "-" {
			break
		}

		colon := findMapColon(trimmed)
		if colon < 0 {
			break
		}

		key := strings.TrimSpace(trimmed[:colon])
		key = unquoteString(key)

		rest := strings.TrimSpace(trimmed[colon+1:])

		p.skipLine() // consume the key line

		var value interface{}

		if rest == "" || rest == "|" || rest == "|-" || rest == ">-" || rest == ">" {
			// Value is on next line(s)
			if rest == "|" || rest == "|-" || rest == ">" || rest == ">-" {
				// Block scalar
				value = p.parseBlockScalarContent(baseIndent+2, rest[0] == '>')
			} else {
				p.skipEmptyLines()
				if p.pos < len(p.input) {
					nextIndent := p.currentIndent()
					if nextIndent > baseIndent {
						// Nested value
						var err error
						value, err = p.parseValue(nextIndent)
						if err != nil {
							return nil, err
						}
					}
				}
			}
		} else if rest[0] == '#' {
			// Comment after key
			value = nil
		} else {
			// Inline value
			value = parseYAMLScalar(rest)
		}

		result[key] = value
	}

	return result, nil
}

func (p *yamlParser) parseSequence(baseIndent int) ([]interface{}, error) {
	var result []interface{}

	for p.pos < len(p.input) {
		p.skipEmptyLines()
		if p.pos >= len(p.input) {
			break
		}

		indent := p.currentIndent()
		if indent < baseIndent {
			break
		}
		if indent > baseIndent {
			break
		}

		line := p.currentLine()
		trimmed := strings.TrimSpace(line)

		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			p.skipLine()
			continue
		}

		if !strings.HasPrefix(trimmed, "- ") && trimmed != "-" {
			break
		}

		p.skipLine()

		var itemStr string
		if len(trimmed) > 2 {
			itemStr = strings.TrimSpace(trimmed[2:])
		}

		var item interface{}
		if itemStr == "" {
			// Multi-line item
			p.skipEmptyLines()
			if p.pos < len(p.input) {
				nextIndent := p.currentIndent()
				if nextIndent > baseIndent {
					var err error
					item, err = p.parseValue(nextIndent)
					if err != nil {
						return nil, err
					}
				}
			}
		} else {
			// Check if the item is a nested mapping
			colon := findMapColon(itemStr)
			if colon >= 0 {
				// This is a mapping item
				savedPos := p.pos
				savedLine := p.line

				// Reconstruct as if we're at the start of the item
				tempInput := strings.Repeat(" ", baseIndent+2) + itemStr + "\n" + p.input[p.pos:]
				tempParser := &yamlParser{input: tempInput, line: p.line}
				tempResult, err := tempParser.parseMapping(baseIndent + 2)
				if err != nil {
					p.pos = savedPos
					p.line = savedLine
					item = parseYAMLScalar(itemStr)
				} else {
					// Advance position by how much the temp parser consumed
					consumed := tempParser.pos - len(strings.Repeat(" ", baseIndent+2)+itemStr+"\n")
					if consumed > 0 && consumed <= len(p.input)-p.pos {
						p.pos += consumed
					}
					item = tempResult
				}
			} else {
				item = parseYAMLScalar(itemStr)
			}
		}

		result = append(result, item)
	}

	return result, nil
}

func (p *yamlParser) parseScalar(indent int) (interface{}, error) {
	line := p.currentLine()
	trimmed := strings.TrimSpace(line)
	p.skipLine()
	return parseYAMLScalar(trimmed), nil
}

func (p *yamlParser) parseBlockScalar(indent int, ch byte) (string, error) {
	line := p.currentLine()
	trimmed := strings.TrimSpace(line)
	p.skipLine()
	folded := ch == '>'
	return p.parseBlockScalarContent(indent+2, folded), nil
}

func (p *yamlParser) parseBlockScalarContent(minIndent int, folded bool) string {
	var lines []string
	var contentIndent = -1

	for p.pos < len(p.input) {
		line := p.currentLine()

		// Check if line is blank
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			lines = append(lines, "")
			p.skipLine()
			continue
		}

		indent := 0
		for indent < len(line) && line[indent] == ' ' {
			indent++
		}

		if contentIndent < 0 {
			contentIndent = indent
		}

		if indent < contentIndent {
			break
		}

		lines = append(lines, line[contentIndent:])
		p.skipLine()
	}

	// Remove trailing empty lines
	for len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}

	if folded {
		return strings.Join(lines, " ") + "\n"
	}
	return strings.Join(lines, "\n") + "\n"
}

func parseYAMLScalar(s string) interface{} {
	if s == "" {
		return nil
	}

	// Check for null
	if s == "null" || s == "~" || s == "Null" || s == "NULL" {
		return nil
	}

	// Check for bool
	switch strings.ToLower(s) {
	case "true", "yes", "on":
		return true
	case "false", "no", "off":
		return false
	}

	// Check for quoted string
	if len(s) >= 2 {
		if s[0] == '"' && s[len(s)-1] == '"' {
			return processEscapes(s[1 : len(s)-1])
		}
		if s[0] == '\'' && s[len(s)-1] == '\'' {
			return s[1 : len(s)-1]
		}
	}

	// Check for inline map or sequence
	if s[0] == '{' {
		v, err := parseInlineMap(s)
		if err == nil {
			return v
		}
	}
	if s[0] == '[' {
		v, err := parseInlineSeq(s)
		if err == nil {
			return v
		}
	}

	// Try integer
	if n, err := strconv.ParseInt(s, 0, 64); err == nil {
		return n
	}

	// Try float
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		return f
	}

	return s
}

func parseInlineMap(s string) (map[string]interface{}, error) {
	// Simple inline map parser: {key: value, key2: value2}
	if !strings.HasPrefix(s, "{") || !strings.HasSuffix(s, "}") {
		return nil, fmt.Errorf("not an inline map")
	}

	inner := s[1 : len(s)-1]
	if strings.TrimSpace(inner) == "" {
		return map[string]interface{}{}, nil
	}

	result := map[string]interface{}{}
	items := splitInlineItems(inner)
	for _, item := range items {
		colon := strings.IndexByte(item, ':')
		if colon < 0 {
			return nil, fmt.Errorf("invalid inline map item: %s", item)
		}
		key := strings.TrimSpace(item[:colon])
		value := strings.TrimSpace(item[colon+1:])
		result[unquoteString(key)] = parseYAMLScalar(value)
	}
	return result, nil
}

func parseInlineSeq(s string) ([]interface{}, error) {
	if !strings.HasPrefix(s, "[") || !strings.HasSuffix(s, "]") {
		return nil, fmt.Errorf("not an inline sequence")
	}

	inner := s[1 : len(s)-1]
	if strings.TrimSpace(inner) == "" {
		return []interface{}{}, nil
	}

	items := splitInlineItems(inner)
	result := make([]interface{}, len(items))
	for i, item := range items {
		result[i] = parseYAMLScalar(strings.TrimSpace(item))
	}
	return result, nil
}

func splitInlineItems(s string) []string {
	var items []string
	var current strings.Builder
	depth := 0
	inSingleQuote := false
	inDoubleQuote := false

	for i := 0; i < len(s); i++ {
		ch := s[i]
		if ch == '\'' && !inDoubleQuote {
			inSingleQuote = !inSingleQuote
			current.WriteByte(ch)
		} else if ch == '"' && !inSingleQuote {
			inDoubleQuote = !inDoubleQuote
			current.WriteByte(ch)
		} else if (ch == '{' || ch == '[') && !inSingleQuote && !inDoubleQuote {
			depth++
			current.WriteByte(ch)
		} else if (ch == '}' || ch == ']') && !inSingleQuote && !inDoubleQuote {
			depth--
			current.WriteByte(ch)
		} else if ch == ',' && depth == 0 && !inSingleQuote && !inDoubleQuote {
			items = append(items, current.String())
			current.Reset()
		} else {
			current.WriteByte(ch)
		}
	}
	if current.Len() > 0 {
		items = append(items, current.String())
	}
	return items
}

func unquoteString(s string) string {
	if len(s) >= 2 {
		if s[0] == '"' && s[len(s)-1] == '"' {
			return processEscapes(s[1 : len(s)-1])
		}
		if s[0] == '\'' && s[len(s)-1] == '\'' {
			return s[1 : len(s)-1]
		}
	}
	return s
}
