func (p *yamlParser) parseBlockScalarContent(minIndent int, folded bool) string {
	var lines []string
	var contentIndent = -1

	for p.pos < len(p.input) {
		line := p.currentLine()

		// Check if line is blank
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			lines = append(lines, "")
			p.skipLine()
			continue
