		}
	}
	if s[0] == '[' {
		v, err := parseInlineSeq(s)
		if err == nil {
			return v
		}
	}

	// Try integer
	if n, err := strconv.ParseInt(s, 0, 64); err == nil {
		return n
	}

	// Try float
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		return f
	}

	return s
}

