		}
		key := strings.TrimSpace(item[:colon])
		value := strings.TrimSpace(item[colon+1:])
		result[unquoteString(key)] = parseYAMLScalar(value)
	}
	return result, nil
}

func parseInlineSeq(s string) ([]interface{}, error) {
