package main

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// marshalYAML converts a value to YAML string
func marshalYAML(v interface{}) (string, error) {
	var sb strings.Builder
	if err := writeYAML(&sb, v, 0, false); err != nil {
		return "", err
	}
	return sb.String(), nil
}

func writeYAML(sb *strings.Builder, v interface{}, indent int, inSequence bool) error {
	switch val := v.(type) {
	case nil:
		sb.WriteString("null\n")
	case bool:
		if val {
			sb.WriteString("true\n")
		} else {
			sb.WriteString("false\n")
		}
	case int:
		sb.WriteString(strconv.Itoa(val) + "\n")
	case int64:
		sb.WriteString(strconv.FormatInt(val, 10) + "\n")
	case float64:
		s := strconv.FormatFloat(val, 'f', -1, 64)
		if !strings.Contains(s, ".") {
			s += ".0"
		}
		sb.WriteString(s + "\n")
	case float32:
		s := strconv.FormatFloat(float64(val), 'f', -1, 32)
		if !strings.Contains(s, ".") {
			s += ".0"
		}
		sb.WriteString(s + "\n")
	case string:
		sb.WriteString(yamlQuoteString(val) + "\n")
	case []byte:
		sb.WriteString(yamlQuoteString(string(val)) + "\n")
	case []interface{}:
		sb.WriteString("\n")
		for _, item := range val {
			sb.WriteString(strings.Repeat(" ", indent) + "- ")
			if err := writeYAML(sb, item, indent+2, true); err != nil {
				return err
			}
		}
	case []string:
		sb.WriteString("\n")
		for _, item := range val {
			sb.WriteString(strings.Repeat(" ", indent) + "- " + yamlQuoteString(item) + "\n")
		}
	case []int64:
		sb.WriteString("\n")
		for _, item := range val {
			sb.WriteString(strings.Repeat(" ", indent) + "- " + strconv.FormatInt(item, 10) + "\n")
		}
	case map[string]interface{}:
		keys := make([]string, 0, len(val))
		for k := range val {
			keys = append(keys, k)
		}
		sort.Strings(keys)

		if len(keys) == 0 {
			sb.WriteString("{}\n")
			return nil
		}

		if !inSequence {
			sb.WriteString("\n")
		}
		for _, k := range keys {
			sb.WriteString(strings.Repeat(" ", indent) + k + ":")
			vv := val[k]
			switch vv.(type) {
			case map[string]interface{}, []interface{}:
				if err := writeYAML(sb, vv, indent+2, false); err != nil {
					return err
				}
			default:
				sb.WriteString(" ")
				if err := writeYAML(sb, vv, indent+2, false); err != nil {
					return err
				}
			}
		}
	case map[interface{}]interface{}:
		// Convert to string map
		strMap := make(map[string]interface{})
		for k, v := range val {
			strMap[fmt.Sprintf("%v", k)] = v
		}
		return writeYAML(sb, strMap, indent, inSequence)
	default:
		sb.WriteString(fmt.Sprintf("%v", v) + "\n")
	}
	return nil
}

func yamlQuoteString(s string) string {
	if s == "" {
		return "\"\""
	}

	// Check if we need to quote
	needsQuote := false

	// Keywords that need quoting
	switch s {
	case "true", "false", "null", "~", "yes", "no", "on", "off":
		needsQuote = true
	}

	if !needsQuote {
		// Check for special chars
		for _, ch := range s {
			if ch == ':' || ch == '{' || ch == '}' || ch == '[' || ch == ']' ||
				ch == ',' || ch == '&' || ch == '*' || ch == '?' || ch == '|' ||
				ch == '-' || ch == '<' || ch == '>' || ch == '=' || ch == '!' ||
				ch == '%' || ch == '@' || ch == '`' || ch == '\n' || ch == '#' {
				needsQuote = true
				break
			}
		}
	}

	if !needsQuote {
		// Check if it looks like a number
		if _, err := strconv.ParseInt(s, 10, 64); err == nil {
			needsQuote = false // Numbers are fine unquoted... actually we return as is
		}
		if _, err := strconv.ParseFloat(s, 64); err == nil {
			needsQuote = false
		}
	}

	if !needsQuote {
		return s
	}

	// Double-quote it
	return "\"" + strings.ReplaceAll(s, "\"", "\\\"") + "\""
}
