				ch == ',' || ch == '&' || ch == '*' || ch == '?' || ch == '|' ||
				ch == '-' || ch == '<' || ch == '>' || ch == '=' || ch == '!' ||
				ch == '%' || ch == '@' || ch == '`' || ch == '\n' || ch == '#' {
