package main

import (
	"fmt"
	"strconv"
	"strings"
)

// parseTOML parses a TOML string
func parseTOML(content string) (map[string]interface{}, error) {
	p := &tomlParser{
		input:  content,
		result: make(map[string]interface{}),
	}
	return p.parse()
}

type tomlParser struct {
	input   string
	pos     int
	result  map[string]interface{}
	current map[string]interface{}
}

func (p *tomlParser) parse() (map[string]interface{}, error) {
	p.current = p.result

	for p.pos < len(p.input) {
		p.skipWhitespaceAndComments()
		if p.pos >= len(p.input) {
			break
		}

		ch := p.input[p.pos]

		if ch == '[' {
			if err := p.parseSection(); err != nil {
				return nil, err
			}
		} else if ch != '\n' {
			if err := p.parseKeyValue(p.current); err != nil {
				return nil, err
			}
		} else {
			p.pos++
		}
	}

	return p.result, nil
}

func (p *tomlParser) skipWhitespaceAndComments() {
	for p.pos < len(p.input) {
		ch := p.input[p.pos]
		if ch == ' ' || ch == '\t' {
			p.pos++
		} else if ch == '#' {
			// Skip to end of line
			for p.pos < len(p.input) && p.input[p.pos] != '\n' {
				p.pos++
			}
		} else if ch == '\n' || ch == '\r' {
			break
		} else {
			break
		}
	}
}

func (p *tomlParser) skipLine() {
	for p.pos < len(p.input) && p.input[p.pos] != '\n' {
		p.pos++
	}
	if p.pos < len(p.input) {
		p.pos++
	}
}

func (p *tomlParser) parseSection() error {
	p.pos++ // skip [
	isArray := false
	if p.pos < len(p.input) && p.input[p.pos] == '[' {
		isArray = true
		p.pos++
	}

	// Read section name
	end := strings.IndexByte(p.input[p.pos:], ']')
	if end < 0 {
		return fmt.Errorf("unclosed section header")
	}

	sectionName := strings.TrimSpace(p.input[p.pos : p.pos+end])
	p.pos += end + 1
	if isArray {
		p.pos++ // skip second ]
	}
	p.skipLine()

	// Navigate to the section
	parts := strings.Split(sectionName, ".")
	current := p.result

	if isArray {
		// [[table]] - array of tables
		for i, part := range parts {
			if i == len(parts)-1 {
				// Last part - create array
				if _, ok := current[part]; !ok {
					current[part] = []interface{}{}
				}
				arr := current[part].([]interface{})
				newTable := make(map[string]interface{})
				current[part] = append(arr, newTable)
				p.current = newTable
			} else {
				if _, ok := current[part]; !ok {
					current[part] = make(map[string]interface{})
				}
				current = current[part].(map[string]interface{})
			}
		}
	} else {
		for _, part := range parts {
			if _, ok := current[part]; !ok {
				current[part] = make(map[string]interface{})
			}
			if m, ok := current[part].(map[string]interface{}); ok {
				current = m
			}
		}
		p.current = current
	}

	return nil
}

func (p *tomlParser) parseKeyValue(m map[string]interface{}) error {
	// Parse key
	key, err := p.parseKey()
	if err != nil {
		return err
	}

	p.skipWhitespaceAndComments()

	if p.pos >= len(p.input) || p.input[p.pos] != '=' {
		return fmt.Errorf("expected '=' after key %q", key)
	}
	p.pos++ // skip =

	p.skipWhitespaceAndComments()

	// Parse value
	value, err := p.parseValue()
	if err != nil {
		return fmt.Errorf("parsing value for key %q: %w", key, err)
	}

	// Handle dotted keys: key.subkey = value
	parts := strings.Split(key, ".")
	current := m
	for i, part := range parts {
		if i == len(parts)-1 {
			current[part] = value
		} else {
			if _, ok := current[part]; !ok {
				current[part] = make(map[string]interface{})
			}
			current = current[part].(map[string]interface{})
		}
	}

	p.skipWhitespaceAndComments()
	if p.pos < len(p.input) && p.input[p.pos] == '#' {
		p.skipLine()
	} else if p.pos < len(p.input) && p.input[p.pos] == '\n' {
		p.pos++
	}

	return nil
}

func (p *tomlParser) parseKey() (string, error) {
	p.skipWhitespaceAndComments()

	if p.pos >= len(p.input) {
		return "", fmt.Errorf("unexpected end of input")
	}

	ch := p.input[p.pos]

	if ch == '"' {
		return p.parseQuotedString()
	}
	if ch == '\'' {
		return p.parseLiteralString()
	}

	// Bare key
	start := p.pos
	for p.pos < len(p.input) {
		ch := p.input[p.pos]
		if ch >= 'a' && ch <= 'z' || ch >= 'A' && ch <= 'Z' || ch >= '0' && ch <= '9' ||
			ch == '_' || ch == '-' || ch == '.' {
			p.pos++
		} else {
			break
		}
	}
	return p.input[start:p.pos], nil
}

func (p *tomlParser) parseValue() (interface{}, error) {
	if p.pos >= len(p.input) {
		return nil, fmt.Errorf("unexpected end of input")
	}

	ch := p.input[p.pos]

	switch {
	case ch == '"':
		if p.pos+2 < len(p.input) && p.input[p.pos:p.pos+3] == `"""` {
			return p.parseMultilineBasicString()
		}
		return p.parseQuotedString()
	case ch == '\'':
		if p.pos+2 < len(p.input) && p.input[p.pos:p.pos+3] == "'''" {
			return p.parseMultilineLiteralString()
		}
		return p.parseLiteralString()
	case ch == '[':
		return p.parseArray()
	case ch == '{':
		return p.parseInlineTable()
	case ch == 't':
		if p.input[p.pos:] >= "true" && len(p.input[p.pos:]) >= 4 && p.input[p.pos:p.pos+4] == "true" {
			p.pos += 4
			return true, nil
		}
	case ch == 'f':
		if len(p.input[p.pos:]) >= 5 && p.input[p.pos:p.pos+5] == "false" {
			p.pos += 5
			return false, nil
		}
	}

	// Try number
	return p.parseNumber()
}

func (p *tomlParser) parseQuotedString() (string, error) {
	p.pos++ // skip "
	var result strings.Builder
	for p.pos < len(p.input) {
		ch := p.input[p.pos]
		if ch == '"' {
			p.pos++
			return result.String(), nil
		}
		if ch == '\\' && p.pos+1 < len(p.input) {
			p.pos++
			switch p.input[p.pos] {
			case 'n':
				result.WriteByte('\n')
			case 't':
				result.WriteByte('\t')
			case 'r':
				result.WriteByte('\r')
			case '"':
				result.WriteByte('"')
			case '\\':
				result.WriteByte('\\')
			default:
				result.WriteByte('\\')
				result.WriteByte(p.input[p.pos])
			}
		} else {
			result.WriteByte(ch)
		}
		p.pos++
	}
	return result.String(), nil
}

func (p *tomlParser) parseLiteralString() (string, error) {
	p.pos++ // skip '
	start := p.pos
	for p.pos < len(p.input) && p.input[p.pos] != '\'' {
		p.pos++
	}
	s := p.input[start:p.pos]
	if p.pos < len(p.input) {
		p.pos++ // skip '
	}
	return s, nil
}

func (p *tomlParser) parseMultilineBasicString() (string, error) {
	p.pos += 3 // skip """
	if p.pos < len(p.input) && p.input[p.pos] == '\n' {
		p.pos++
	}
	var result strings.Builder
	for p.pos < len(p.input) {
		if p.pos+2 < len(p.input) && p.input[p.pos:p.pos+3] == `"""` {
			p.pos += 3
			return result.String(), nil
		}
		ch := p.input[p.pos]
		if ch == '\\' && p.pos+1 < len(p.input) {
			p.pos++
			switch p.input[p.pos] {
			case 'n':
				result.WriteByte('\n')
			case 't':
				result.WriteByte('\t')
			case '"':
				result.WriteByte('"')
			case '\\':
				result.WriteByte('\\')
			case '\n':
				// Line ending backslash - skip whitespace
				p.pos++
				for p.pos < len(p.input) && (p.input[p.pos] == ' ' || p.input[p.pos] == '\t' || p.input[p.pos] == '\n' || p.input[p.pos] == '\r') {
					p.pos++
				}
				continue
			default:
				result.WriteByte('\\')
				result.WriteByte(p.input[p.pos])
			}
		} else {
			result.WriteByte(ch)
		}
		p.pos++
	}
	return result.String(), fmt.Errorf("unterminated multiline string")
}

func (p *tomlParser) parseMultilineLiteralString() (string, error) {
	p.pos += 3 // skip '''
	if p.pos < len(p.input) && p.input[p.pos] == '\n' {
		p.pos++
	}
	start := p.pos
	for p.pos < len(p.input) {
		if p.pos+2 < len(p.input) && p.input[p.pos:p.pos+3] == "'''" {
			s := p.input[start:p.pos]
			p.pos += 3
			return s, nil
		}
		p.pos++
	}
	return p.input[start:], fmt.Errorf("unterminated multiline literal string")
}

func (p *tomlParser) parseArray() ([]interface{}, error) {
	p.pos++ // skip [
	var result []interface{}

	for {
		// Skip whitespace/newlines/comments
		for p.pos < len(p.input) {
			ch := p.input[p.pos]
			if ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' {
				p.pos++
			} else if ch == '#' {
				p.skipLine()
			} else {
				break
			}
		}

		if p.pos >= len(p.input) {
			return nil, fmt.Errorf("unterminated array")
		}

		if p.input[p.pos] == ']' {
			p.pos++
			return result, nil
		}

		value, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		result = append(result, value)

		// Skip whitespace/comments
		for p.pos < len(p.input) {
			ch := p.input[p.pos]
			if ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' {
				p.pos++
			} else if ch == '#' {
				p.skipLine()
			} else {
				break
			}
		}

		if p.pos < len(p.input) && p.input[p.pos] == ',' {
			p.pos++
		}
	}
}

func (p *tomlParser) parseInlineTable() (map[string]interface{}, error) {
	p.pos++ // skip {
	result := make(map[string]interface{})

	for {
		p.skipWhitespaceAndComments()

		if p.pos >= len(p.input) {
			return nil, fmt.Errorf("unterminated inline table")
		}

		if p.input[p.pos] == '}' {
			p.pos++
			return result, nil
		}

		if err := p.parseKeyValue(result); err != nil {
			return nil, err
		}

		p.skipWhitespaceAndComments()

		if p.pos < len(p.input) && p.input[p.pos] == ',' {
			p.pos++
		}
	}
}

func (p *tomlParser) parseNumber() (interface{}, error) {
	start := p.pos

	// Skip sign
	if p.pos < len(p.input) && (p.input[p.pos] == '+' || p.input[p.pos] == '-') {
		p.pos++
	}

	isFloat := false
	for p.pos < len(p.input) {
		ch := p.input[p.pos]
		if ch >= '0' && ch <= '9' || ch == '_' {
			p.pos++
		} else if ch == '.' || ch == 'e' || ch == 'E' {
			isFloat = true
			p.pos++
		} else {
			break
		}
	}

	s := strings.ReplaceAll(p.input[start:p.pos], "_", "")

	if isFloat {
		f, err := strconv.ParseFloat(s, 64)
		if err != nil {
			return nil, fmt.Errorf("invalid number: %s", s)
		}
		return f, nil
	}

	n, err := strconv.ParseInt(s, 0, 64)
	if err != nil {
		return nil, fmt.Errorf("invalid integer: %s", s)
	}
	return n, nil
}

// marshalTOML converts a value to TOML format
func marshalTOML(v interface{}) (string, error) {
	m, ok := v.(map[string]interface{})
	if !ok {
		return "", fmt.Errorf("TOML marshaling requires a map, got %T", v)
	}

	var sb strings.Builder
	if err := writeTOML(&sb, m, ""); err != nil {
		return "", err
	}
	return sb.String(), nil
}

func writeTOML(sb *strings.Builder, m map[string]interface{}, prefix string) error {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	// Write simple values first
	for _, k := range keys {
		v := m[k]
		switch v.(type) {
		case map[string]interface{}, []interface{}:
			// Skip complex values for now
		default:
			sb.WriteString(k + " = ")
			if err := writeTOMLValue(sb, v); err != nil {
				return err
			}
			sb.WriteString("\n")
		}
	}

	// Write complex values
	for _, k := range keys {
		v := m[k]
		switch vv := v.(type) {
		case map[string]interface{}:
			var sectionName string
			if prefix != "" {
				sectionName = prefix + "." + k
			} else {
				sectionName = k
			}
			sb.WriteString("\n[" + sectionName + "]\n")
			if err := writeTOML(sb, vv, sectionName); err != nil {
				return err
			}
		case []interface{}:
			// Check if it's an array of tables
			if len(vv) > 0 {
				if _, ok := vv[0].(map[string]interface{}); ok {
					var sectionName string
					if prefix != "" {
						sectionName = prefix + "." + k
					} else {
						sectionName = k
					}
					for _, item := range vv {
						sb.WriteString("\n[[" + sectionName + "]]\n")
						if tm, ok := item.(map[string]interface{}); ok {
							if err := writeTOML(sb, tm, sectionName); err != nil {
								return err
							}
						}
					}
				} else {
					sb.WriteString(k + " = ")
					if err := writeTOMLValue(sb, v); err != nil {
						return err
					}
					sb.WriteString("\n")
				}
			}
		}
	}

	return nil
}

func writeTOMLValue(sb *strings.Builder, v interface{}) error {
	switch vv := v.(type) {
	case nil:
		sb.WriteString(`""`)
	case bool:
		if vv {
			sb.WriteString("true")
		} else {
			sb.WriteString("false")
		}
	case int:
		sb.WriteString(strconv.Itoa(vv))
	case int64:
		sb.WriteString(strconv.FormatInt(vv, 10))
	case float64:
		sb.WriteString(strconv.FormatFloat(vv, 'f', -1, 64))
	case string:
		sb.WriteString(`"` + strings.ReplaceAll(vv, `"`, `\"`) + `"`)
	case []interface{}:
		sb.WriteString("[")
		for i, item := range vv {
			if i > 0 {
				sb.WriteString(", ")
			}
			if err := writeTOMLValue(sb, item); err != nil {
				return err
			}
		}
		sb.WriteString("]")
	default:
		sb.WriteString(fmt.Sprintf("%v", v))
	}
	return nil
}

