					if err := writeTOMLValue(sb, v); err != nil {
						return err
					}
					sb.WriteString("\n")
				}
			}
		}
	}

	return nil
}

func writeTOMLValue(sb *strings.Builder, v interface{}) error {
	switch vv := v.(type) {
	case nil:
		sb.WriteString(`""`)
	case bool:
		if vv {
			sb.WriteString("true")
		} else {
			sb.WriteString("false")
		}
