// createTemplate creates a new template with all the gomplate functions
func createTemplate(cfg *Config, name string) (*template.Template, error) {
	t := template.New(name)

	// Set delimiters
	t = t.Delims(cfg.LeftDelim, cfg.RightDelim)

	// Set missing key behavior
	switch cfg.MissingKey {
	case "zero":
		t = t.Option("missingkey=zero")
	case "default", "invalid":
		t = t.Option("missingkey=default")
	default: // "error"
		t = t.Option("missingkey=error")
	}

	// Register all functions - initially without tmpl namespace
	// We'll add tmpl namespace separately after the template is set up
	funcs := buildFuncMap(cfg, nil)
	t = t.Funcs(funcs)

	return t, nil
}

// createTemplateWithSelf creates a template that has self-reference for tmpl namespace
func createTemplateWithSelf(cfg *Config, name string) (*template.Template, error) {
	t, err := createTemplate(cfg, name)
	if err != nil {
		return nil, err
	}

	// Create tmpl namespace that will reference this template
	tmplNS := &TmplNS{cfg: cfg}
	t.Funcs(template.FuncMap{
		"tmpl": func() *TmplNS { return tmplNS },
		"tpl": func(args ...interface{}) (string, error) {
			return tmplNS.Inline(args...)
		},
	})

	// The tmplNS will be set once the template is fully initialized
	// We'll use a pointer trick

	return t, nil
}

// buildFuncMap creates all template functions
