		return (&TestNS{}).Fail(args...)
	}
	fm["required"] = func(args ...interface{}) (interface{}, error) {
		return (&TestNS{}).Required(args...)
	}
	fm["isKind"] = func(kind string, value interface{}) bool {
		return (&TestNS{}).IsKind(kind, value)
	}
	fm["kind"] = func(value interface{}) string {
		return (&TestNS{}).Kind(value)
	}

	// Plugin functions
	for name, pluginPath := range cfg.plugins {
		name := name
		pluginPath := pluginPath
		fm[name] = makePluginFunc(name, pluginPath, cfg)
	}

	// Namespace accessor functions
	mathNS := &MathNS{}
	stringsNS := &StringsNS{}
