	semverNS := &SemverNS{}
	awsNS := &AWSNS{}
	gcpNS := &GCPNS{}
	envNS := &EnvNS{}

	fm["math"] = func() *MathNS { return mathNS }
	fm["strings"] = func() *StringsNS { return stringsNS }
	fm["conv"] = func() *ConvNS { return convNS }
	fm["coll"] = func() *CollNS { return collNS }
