func makePluginFunc(name, pluginPath string, cfg *Config) interface{} {
	return func(args ...interface{}) (string, error) {
		timeout := 5 * time.Second
		if v := os.Getenv("GOMPLATE_PLUGIN_TIMEOUT"); v != "" {
			if d, err := time.ParseDuration(v); err == nil {
				timeout = d
			}
		}

		strArgs := make([]string, len(args))
		for i, a := range args {
			strArgs[i] = fmt.Sprintf("%v", a)
		}

		ctx, cancel := context.WithTimeout(context.Background(), timeout)
		defer cancel()

		cmd := exec.CommandContext(ctx, pluginPath, strArgs...)
		cmd.Stderr = os.Stderr
		out, err := cmd.Output()
		if err != nil {
			return "", fmt.Errorf("plugin %q failed: %w", name, err)
		}
		return string(out), nil
	}
}

// TmplNS namespace
type TmplNS struct {
	cfg *Config
	t   *template.Template  // Set after template creation
}

func newTmplNS(cfg *Config) *TmplNS {
	return &TmplNS{cfg: cfg}
}

func (ns *TmplNS) Exec(name string, ctx ...interface{}) (string, error) {
	if ns.t == nil {
		return "", fmt.Errorf("template not initialized")
	}

	tmpl := ns.t.Lookup(name)
	if tmpl == nil {
		return "", fmt.Errorf("template %q not found", name)
	}

	var data interface{}
	if len(ctx) > 0 {
		data = ctx[0]
	}

	var buf strings.Builder
	if err := tmpl.Execute(&buf, data); err != nil {
		return "", err
	}
	return buf.String(), nil
}

func (ns *TmplNS) Inline(args ...interface{}) (string, error) {
	// tmpl.Inline [name] in [context]
	if len(args) == 0 {
		return "", fmt.Errorf("tmpl.Inline requires at least one argument")
	}

	var name, in string
	var ctx interface{}

	switch len(args) {
	case 1:
		in = fmt.Sprintf("%v", args[0])
	case 2:
		// Could be (name, in) or (in, context)
		switch args[1].(type) {
		case string:
			name = fmt.Sprintf("%v", args[0])
			in = fmt.Sprintf("%v", args[1])
		default:
			in = fmt.Sprintf("%v", args[0])
			ctx = args[1]
		}
	case 3:
		name = fmt.Sprintf("%v", args[0])
		in = fmt.Sprintf("%v", args[1])
		ctx = args[2]
	}

	var t *template.Template
	if ns.t != nil && name != "" {
		// Check if already defined
		existing := ns.t.Lookup(name)
		if existing != nil {
			var buf strings.Builder
			if err := existing.Execute(&buf, ctx); err != nil {
				return "", err
			}
			return buf.String(), nil
		}
		t = ns.t
	} else {
		t = template.New("<inline>")
		t.Delims(ns.cfg.LeftDelim, ns.cfg.RightDelim)
		t.Funcs(buildFuncMap(ns.cfg, nil))
		// Add tmpl namespace
		tmplNS2 := &TmplNS{cfg: ns.cfg, t: t}
		t.Funcs(template.FuncMap{
			"tmpl": func() *TmplNS { return tmplNS2 },
			"tpl": func(args2 ...interface{}) (string, error) {
				return tmplNS2.Inline(args2...)
			},
		})
	}

	var err error
	if name != "" {
		_, err = t.New(name).Parse(in)
	} else {
		t, err = t.New("<inline>").Parse(in)
	}
	if err != nil {
		return "", err
	}

	var execT *template.Template
	if name != "" {
		execT = t.Lookup(name)
	} else {
		execT = t.Lookup("<inline>")
	}
	if execT == nil {
		return "", fmt.Errorf("template not found")
	}

	var buf strings.Builder
	if err := execT.Execute(&buf, ctx); err != nil {
		return "", err
	}
	return buf.String(), nil
}

func (ns *TmplNS) Path() string {
	return ns.cfg.currentTemplateFile
}

